// ─────────────────────────────────────────────────────────────────────────
// États globaux window.__agon* — récapitulatif (coordination entre script.js
// et les templates views/*.html, ou entre la page index et l'iframe /debate).
// Ne pas renommer/supprimer sans vérifier toutes les occurrences ci-dessous.
//
// - __agonDebateModalOpen
//     Écrit : ouverture/fermeture de la modale débat (index).
//     Lu : auto-scroll des médias index, idle guard, refresh en arrière-plan
//          — tous suspendus pendant que la modale est ouverte.
// - __agonDebateModalOpenedFromNotifications
//     Écrit à l'ouverture de la modale (selon location.pathname === "/notifications").
//     Lu pour déterminer le comportement de fermeture/retour de la modale.
// - __agonDebateModalNewDebateCreated
//     Écrit quand un débat est créé depuis la modale.
//     Lu+remis à false par l'index pour rafraîchir/insérer ce débat.
// - __agonDebateModalPendingDebates
//     Écrit avec la liste fraîche de débats pendant que la modale est ouverte.
//     Lu+vidé à la fermeture de la modale pour appliquer le rafraîchissement
//     différé sans perturber l'affichage pendant que la modale est ouverte.
// - __agonIframeCurrentPathname
//     Écrit par l'iframe /debate (pathname courant affiché dans la modale).
//     Lu par le parent (index) pour la gestion du bouton retour/navigation.
// - __agonDebateBackNavigationInitialized
//     Garde d'idempotence : empêche de rebrancher plusieurs fois le handler
//     de navigation retour de la modale débat.
// - __agonPrefetchedDebateData
//     Écrit par l'index (préchargement des données d'un débat avant ouverture
//     de sa modale), sous la forme { id, debate }.
//     Lu+vidé par loadDebate() dans l'iframe (window.parent.__agonPrefetchedDebateData)
//     pour afficher instantanément le débat sans nouvel appel API.
// - __agonSuspendedIndexEmbeds
//     Écrit à l'ouverture de la modale (état des embeds index suspendus :
//     vidéos/iframes mis en pause).
//     Lu+vidé à la fermeture pour restaurer ces embeds.
// - __agonIdleHomeGuard
//     Défini dans views/create.html, notifications.html et debate.html sous la
//     forme { check, markHidden, markVisible } (logique propre à chaque page).
//     Lu par script.js pour rediriger vers l'accueil si la page est restée
//     inactive trop longtemps.
// - __agonIndexShareDropdownScan
//     Défini dans views/index.html (= scheduleScan).
//     Appelé par initIndexCardShareMenus() sur la page d'accueil à la place de
//     son scan générique, car l'index a sa propre logique optimisée.
// - __agonIndexStatsScan
//     Défini dans views/index.html (= scheduleScanCards).
//     Appelé par script.js après rendu de cartes pour rescanner les
//     statistiques/badges IA des cartes de l'index.
// - __agonIdeaXMobileColumnFitBound
//     Garde d'idempotence : empêche de rebrancher plusieurs fois l'observer de
//     mise à l'échelle des embeds X (Twitter) en colonne mobile.
// ─────────────────────────────────────────────────────────────────────────

const API = "/api";

// Cache du breakpoint 768px : évite de créer/interroger un MediaQueryList
// à chaque appel dans les IntersectionObserver callbacks et handlers scroll.
const _mq768 = typeof window !== "undefined" && window.matchMedia ? window.matchMedia("(max-width: 768px)") : null;
let _isMobile768 = _mq768 ? _mq768.matches : false;
if (_mq768) _mq768.addEventListener("change", (e) => { _isMobile768 = e.matches; });

const COLOR_A          = '#516776';
const COLOR_A_BG       = '#a0c6d4';
const COLOR_A_BORDER   = '#516776';
const COLOR_B          = '#AEC0CC';
const COLOR_B_BG       = '#e8f3f7';
const COLOR_B_BORDER   = '#AEC0CC';

// DIAGNOSTIC TEMPORAIRE — à retirer une fois le bug du "refresh" de l'index résolu.
// Trace tous les déclencheurs suspects de reload/navigation/loader/rerender.
// Mettre __AGON_DEBUG_REFRESH_ENABLED = true pour réactiver (désactivé en prod
// Activé temporairement pour diagnostiquer les rechargements spontanés mobile.
// pour éviter console.log + localStorage synchrone à chaque interaction).
const __AGON_DEBUG_REFRESH_ENABLED = true;
const AGON_LAST_LIFECYCLE_SNAPSHOT_KEY = "agon_last_lifecycle_snapshot";
const AGON_LAST_HEARTBEAT_KEY = "agon_last_heartbeat";
const AGON_FREEZE_LOG_KEY = "agon_freeze_log";
let __agonLastHiddenAt = 0;
let __agonLastVisibleAt = Date.now();
let __agonLastUserInputAt = 0;
let __agonLastRuntimeError = null;

function __agonGetModalDebugContext() {
  try {
    const modal = document.getElementById("debate-iframe-modal");
    const closeButton = document.getElementById("debate-iframe-modal-close");
    const frame = document.getElementById("debate-iframe-modal-frame");
    const closeRect = closeButton ? closeButton.getBoundingClientRect() : null;
    const closeStyle = closeButton ? window.getComputedStyle(closeButton) : null;
    return {
      modalExists: !!modal,
      modalOpen: window.__agonDebateModalOpen === true || !!modal?.classList?.contains("open"),
      iframePathname: String(window.__agonIframeCurrentPathname || ""),
      modalClassName: modal ? String(modal.className || "") : "",
      frameSrc: frame ? String(frame.getAttribute("src") || frame.src || "") : "",
      scrollLockMode: typeof _debateModalScrollLockMode !== "undefined" ? String(_debateModalScrollLockMode || "") : "",
      htmlOverflow: document.documentElement.style.overflow || "",
      bodyOverflow: document.body?.style?.overflow || "",
      bodyPosition: document.body?.style?.position || "",
      bodyTop: document.body?.style?.top || "",
      closeButtonExists: !!closeButton,
      closeButtonDisplay: closeStyle?.display || "",
      closeButtonVisibility: closeStyle?.visibility || "",
      closeButtonOpacity: closeStyle?.opacity || "",
      closeButtonPointerEvents: closeStyle?.pointerEvents || "",
      closeButtonRect: closeRect ? {
        x: Math.round(closeRect.x),
        y: Math.round(closeRect.y),
        width: Math.round(closeRect.width),
        height: Math.round(closeRect.height)
      } : null
    };
  } catch (e) {
    return { modalDebugError: String(e?.message || e || "") };
  }
}

function __agonStoreFreezeLog(entry = {}) {
  if (!__AGON_DEBUG_REFRESH_ENABLED) return;
  try {
    const prev = JSON.parse(localStorage.getItem(AGON_FREEZE_LOG_KEY) || "[]");
    prev.unshift({
      timestamp: new Date().toISOString(),
      url: String(window.location.href || ""),
      ...__agonGetDebugRuntimeContext(),
      ...entry
    });
    if (prev.length > 20) prev.length = 20;
    localStorage.setItem(AGON_FREEZE_LOG_KEY, JSON.stringify(prev));
  } catch (e) {}
}

function __agonGetDebugRuntimeContext(extra = {}) {
  const now = Date.now();
  let memory = null;
  try {
    if (performance.memory) {
      memory = {
        usedJSHeapSize: performance.memory.usedJSHeapSize || null,
        totalJSHeapSize: performance.memory.totalJSHeapSize || null,
        jsHeapSizeLimit: performance.memory.jsHeapSizeLimit || null
      };
    }
  } catch (e) {}

  let connection = null;
  try {
    const c = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
    if (c) {
      connection = {
        effectiveType: c.effectiveType || null,
        downlink: c.downlink || null,
        rtt: c.rtt || null,
        saveData: c.saveData === true
      };
    }
  } catch (e) {}

  return {
    visibilityState: document.visibilityState || "",
    hidden: document.hidden === true,
    online: navigator.onLine !== false,
    wasDiscarded: document.wasDiscarded === true,
    standalone: !!(window.navigator.standalone || window.matchMedia?.("(display-mode: standalone)")?.matches),
    timeSinceHiddenMs: __agonLastHiddenAt ? now - __agonLastHiddenAt : null,
    timeSinceVisibleMs: __agonLastVisibleAt ? now - __agonLastVisibleAt : null,
    timeSinceUserInputMs: __agonLastUserInputAt ? now - __agonLastUserInputAt : null,
    viewport: {
      width: window.innerWidth || null,
      height: window.innerHeight || null,
      devicePixelRatio: window.devicePixelRatio || null
    },
    deviceMemory: navigator.deviceMemory || null,
    hardwareConcurrency: navigator.hardwareConcurrency || null,
    memory,
    connection,
    lastRuntimeError: __agonLastRuntimeError,
    modal: __agonGetModalDebugContext(),
    ...extra
  };
}

function __agonStoreLifecycleSnapshot(reason, extra = {}) {
  if (!__AGON_DEBUG_REFRESH_ENABLED) return;
  try {
    localStorage.setItem(AGON_LAST_LIFECYCLE_SNAPSHOT_KEY, JSON.stringify({
      reason,
      timestamp: new Date().toISOString(),
      url: String(window.location.href || ""),
      scrollY: Math.round(window.scrollY || 0),
      modalOpen: window.__agonDebateModalOpen === true,
      ...__agonGetDebugRuntimeContext(extra)
    }));
  } catch (e) {}
}

function __agonDebugRefreshLog(source, type, extra = {}) {
  if (!__AGON_DEBUG_REFRESH_ENABLED) return;
  try {
    const entry = {
      source,
      type,
      timestamp: new Date().toISOString(),
      url: String(window.location.href || ""),
      scrollY: Math.round(window.scrollY || 0),
      modalOpen: window.__agonDebateModalOpen === true,
      ...__agonGetDebugRuntimeContext(),
      ...extra
    };
    console.log("[AGON DEBUG REFRESH]", entry);
    try {
      const KEY = "agon_refresh_log";
      const prev = JSON.parse(localStorage.getItem(KEY) || "[]");
      prev.unshift(entry);
      if (prev.length > 30) prev.length = 30;
      localStorage.setItem(KEY, JSON.stringify(prev));
    } catch (e2) {}
  } catch (e) {}
}

// DIAGNOSTIC TEMPORAIRE — à appeler juste avant tout location.reload()/replace()/href
// connu du code Agôn, pour pouvoir distinguer au prochain démarrage un reload
// déclenché par notre propre code d'un reload déclenché par le navigateur mobile
// (onglet déchargé pour mémoire) ou d'un crash/timeout réseau dont notre code n'a
// pas connaissance (dans ce dernier cas, aucun motif ne sera trouvé au démarrage).
const AGON_LAST_RELOAD_REASON_KEY = "agon_last_reload_reason";
function __agonRecordReloadReason(reason) {
  try {
    sessionStorage.setItem(AGON_LAST_RELOAD_REASON_KEY, JSON.stringify({ reason, at: Date.now() }));
  } catch (e) {}
}

// DIAGNOSTIC TEMPORAIRE — s'exécute au tout début de chaque chargement de script.js.
(function __agonDebugStartupDiagnostic() {
  try {
    let navigationType = "unknown";
    try {
      const navEntry = performance.getEntriesByType && performance.getEntriesByType("navigation")[0];
      if (navEntry) {
        navigationType = navEntry.type;
      } else if (performance.navigation) {
        navigationType = ["navigate", "reload", "back_forward", "reserved"][performance.navigation.type] || "unknown";
      }
    } catch (e) {}

    const wasDiscarded = document.wasDiscarded === true;
    let lastLifecycleSnapshot = null;
    try {
      const rawLifecycle = localStorage.getItem(AGON_LAST_LIFECYCLE_SNAPSHOT_KEY);
      if (rawLifecycle) lastLifecycleSnapshot = JSON.parse(rawLifecycle);
    } catch (e) {}

    let lastHeartbeat = null;
    try {
      const rawHeartbeat = localStorage.getItem(AGON_LAST_HEARTBEAT_KEY);
      if (rawHeartbeat) lastHeartbeat = JSON.parse(rawHeartbeat);
    } catch (e) {}

    let lastReloadReason = null;
    try {
      const raw = sessionStorage.getItem(AGON_LAST_RELOAD_REASON_KEY);
      if (raw) {
        lastReloadReason = JSON.parse(raw);
        sessionStorage.removeItem(AGON_LAST_RELOAD_REASON_KEY);
      }
    } catch (e) {}

    const skipStartup = window.__agonSkipStartupOnce === true;

    // Un déchargement normal (navigation, fermeture) écrit toujours un snapshot
    // "pagehide"/"beforeunload" en dernier. Si le dernier snapshot est un simple
    // changement de visibilité récent, la page précédente est morte sans être
    // déchargée proprement : processus WebKit tué (mémoire) ou crashé.
    const lifecycleAgeMs = lastLifecycleSnapshot?.timestamp
      ? Date.now() - new Date(lastLifecycleSnapshot.timestamp).getTime()
      : null;
    const heartbeatAgeMs = lastHeartbeat?.timestamp
      ? Date.now() - new Date(lastHeartbeat.timestamp).getTime()
      : null;
    const lifecycleWasCleanUnload =
      lastLifecycleSnapshot?.reason === "pagehide" ||
      lastLifecycleSnapshot?.reason === "beforeunload";
    const isStandaloneDisplay = !!(window.navigator.standalone || window.matchMedia?.("(display-mode: standalone)")?.matches);

    let likelyCause = "navigation normale (premier chargement ou lien cliqué)";
    if (lastReloadReason) {
      likelyCause = "code Agôn : " + lastReloadReason.reason;
    } else if (navigationType === "reload" && wasDiscarded) {
      likelyCause = "navigateur mobile : onglet déchargé pour mémoire puis rechargé (tab discard)";
    } else if (navigationType === "reload" && !wasDiscarded) {
      likelyCause = "reload sans motif connu de notre code : navigateur/OS, crash, ou erreur réseau/surcharge indéterminée";
    } else if (wasDiscarded) {
      likelyCause = "navigateur mobile : onglet déchargé pour mémoire (tab discard)";
    } else if (
      navigationType === "navigate" &&
      lastLifecycleSnapshot &&
      !lifecycleWasCleanUnload &&
      lifecycleAgeMs !== null &&
      lifecycleAgeMs >= 0 &&
      lifecycleAgeMs < 10 * 60 * 1000
    ) {
      likelyCause = isStandaloneDisplay
        ? "processus WebKit tué/crashé sans pagehide (mémoire probable) puis relance de la PWA standalone sur son URL de départ"
        : "page précédente morte sans pagehide (kill mémoire ou crash) puis nouvelle navigation";
    }

    // Après un kill WebKit sans pagehide en standalone, iOS relance toujours la
    // PWA sur son start_url ("/"), quelle que soit la page affichée avant le kill.
    // On restaure la page précédente pour éviter à l'utilisateur de perdre sa
    // place (perçu comme un "refresh intempestif"). Ciblé strictement sur ce cas
    // précis (pas un clean unload, pas un skipStartup volontaire vers l'accueil,
    // pas déjà sur la bonne page) pour ne jamais interférer avec une navigation
    // normale ou l'ouverture d'un lien de notification.
    let restoredTo = null;
    const isLikelyStandaloneKillRelaunch =
      isStandaloneDisplay &&
      likelyCause === "processus WebKit tué/crashé sans pagehide (mémoire probable) puis relance de la PWA standalone sur son URL de départ";
    if (isLikelyStandaloneKillRelaunch && !skipStartup && window.location.pathname === "/" && lastLifecycleSnapshot?.url) {
      try {
        const previousUrl = new URL(lastLifecycleSnapshot.url, window.location.origin);
        const target = previousUrl.pathname + previousUrl.search + previousUrl.hash;
        const current = window.location.pathname + window.location.search + window.location.hash;
        if (previousUrl.origin === window.location.origin && target !== "/" && target !== current) {
          restoredTo = target;
        }
      } catch (e) {}
    }

    if (__AGON_DEBUG_REFRESH_ENABLED) {
      const entry = {
        navigationType,
        wasDiscarded,
        lastReloadReason: lastReloadReason ? lastReloadReason.reason : null,
        lastReloadReasonAt: lastReloadReason ? new Date(lastReloadReason.at).toISOString() : null,
        skipStartup,
        likelyCause,
        restoredTo,
        timestamp: new Date().toISOString(),
        url: String(window.location.href || ""),
        userAgent: String(navigator.userAgent || ""),
        previousLifecycleReason: lastLifecycleSnapshot?.reason || null,
        previousLifecycleAt: lastLifecycleSnapshot?.timestamp || null,
        previousLifecycleAgeMs: lifecycleAgeMs,
        previousLifecycleUrl: lastLifecycleSnapshot?.url || null,
        previousLifecycleModalOpen: lastLifecycleSnapshot?.modalOpen ?? null,
        previousLifecycleHidden: lastLifecycleSnapshot?.hidden ?? null,
        previousLifecyclePagehidePersisted: lastLifecycleSnapshot?.pagehidePersisted ?? null,
        previousLifecycleTimeSinceHiddenMs: lastLifecycleSnapshot?.timeSinceHiddenMs ?? null,
        previousLifecycleLastRuntimeError: lastLifecycleSnapshot?.lastRuntimeError || null,
        previousLifecycleMemory: lastLifecycleSnapshot?.memory || null,
        previousLifecycleModal: lastLifecycleSnapshot?.modal || null,
        previousHeartbeatAt: lastHeartbeat?.timestamp || null,
        previousHeartbeatAgeMs: heartbeatAgeMs,
        previousHeartbeatUrl: lastHeartbeat?.url || null,
        previousHeartbeatModal: lastHeartbeat?.modal || null,
        ...__agonGetDebugRuntimeContext()
      };
      console.log("[AGON DEBUG STARTUP]", entry);
      try {
        const KEY = "agon_startup_log";
        const prev = JSON.parse(localStorage.getItem(KEY) || "[]");
        prev.unshift(entry);
        if (prev.length > 20) prev.length = 20;
        localStorage.setItem(KEY, JSON.stringify(prev));
      } catch (e2) {}
    }

    if (restoredTo) {
      window.location.replace(restoredTo);
    }
  } catch (e) {}
})();

["pointerdown", "touchstart", "keydown", "click"].forEach((eventName) => {
  window.addEventListener(eventName, () => {
    __agonLastUserInputAt = Date.now();
  }, { passive: true, capture: true });
});

window.addEventListener("error", (event) => {
  __agonLastRuntimeError = {
    type: "error",
    message: String(event.message || ""),
    source: String(event.filename || ""),
    line: event.lineno || null,
    column: event.colno || null,
    at: new Date().toISOString()
  };
  __agonDebugRefreshLog("window-error", "error", { error: __agonLastRuntimeError });
});

window.addEventListener("unhandledrejection", (event) => {
  const reason = event.reason;
  __agonLastRuntimeError = {
    type: "unhandledrejection",
    message: String(reason?.message || reason || ""),
    at: new Date().toISOString()
  };
  __agonDebugRefreshLog("window-unhandledrejection", "error", { error: __agonLastRuntimeError });
});

window.addEventListener("pagehide", (event) => {
  __agonStoreLifecycleSnapshot("pagehide", { pagehidePersisted: event.persisted === true });
  __agonDebugRefreshLog("window-pagehide", "lifecycle", { persisted: event.persisted === true });
}, true);

window.addEventListener("beforeunload", () => {
  __agonStoreLifecycleSnapshot("beforeunload");
  __agonDebugRefreshLog("window-beforeunload", "lifecycle");
}, true);

document.addEventListener("freeze", () => {
  __agonStoreLifecycleSnapshot("document-freeze");
  __agonDebugRefreshLog("document-freeze", "lifecycle");
}, true);

document.addEventListener("resume", () => {
  __agonLastVisibleAt = Date.now();
  __agonDebugRefreshLog("document-resume", "lifecycle");
}, true);

document.addEventListener("visibilitychange", () => {
  if (document.hidden) {
    __agonLastHiddenAt = Date.now();
    __agonStoreLifecycleSnapshot("visibility-hidden");
  } else {
    __agonLastVisibleAt = Date.now();
    __agonStoreLifecycleSnapshot("visibility-visible");
  }
  __agonDebugRefreshLog("document-visibilitychange", "rerender", { hidden: document.hidden });
});

(function __agonBindFreezeHeartbeat() {
  if (!__AGON_DEBUG_REFRESH_ENABLED) return;
  const HEARTBEAT_INTERVAL_MS = 5000;
  const STALL_THRESHOLD_MS = 12000;
  let expectedNextBeat = Date.now() + HEARTBEAT_INTERVAL_MS;

  function writeHeartbeat(reason = "heartbeat") {
    try {
      localStorage.setItem(AGON_LAST_HEARTBEAT_KEY, JSON.stringify({
        reason,
        timestamp: new Date().toISOString(),
        url: String(window.location.href || ""),
        ...__agonGetDebugRuntimeContext()
      }));
    } catch (e) {}
  }

  writeHeartbeat("startup");
  window.addEventListener("pagehide", () => writeHeartbeat("pagehide"), true);
  document.addEventListener("visibilitychange", () => {
    expectedNextBeat = Date.now() + HEARTBEAT_INTERVAL_MS;
    writeHeartbeat(document.hidden ? "hidden" : "visible");
  }, true);

  window.setInterval(() => {
    const now = Date.now();
    const driftMs = now - expectedNextBeat;
    const wasVisible = !document.hidden;
    writeHeartbeat("interval");
    if (wasVisible && driftMs > STALL_THRESHOLD_MS) {
      __agonStoreFreezeLog({
        source: "heartbeat",
        type: "main-thread-stall",
        driftMs,
        thresholdMs: STALL_THRESHOLD_MS
      });
    }
    expectedNextBeat = now + HEARTBEAT_INTERVAL_MS;
  }, HEARTBEAT_INTERVAL_MS);
})();

function registerServiceWorker() {
  if (!("serviceWorker" in navigator)) return;

  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/service-worker.js", { updateViaCache: "none" })
      .then((registration) => registration.update?.())
      .catch(() => {});
  });

  // Le service worker sert le HTML en cache instantanément au lancement standalone,
  // puis revalide en arrière-plan. Si cette revalidation détecte que le HTML affiché
  // est obsolète (ex. juste après un déploiement, décalage avec le CSS/JS déjà à
  // jour), il prévient la page ici pour qu'elle se recharge une seule fois.
  navigator.serviceWorker.addEventListener("message", (event) => {
    if (event.data?.type !== "agon:page-stale" || window.__agonStalePageRefreshed) return;
    window.__agonStalePageRefreshed = true;
    forceFullPageRefresh();
  });
}

registerServiceWorker();

// Bouton "Actualiser" : depuis que le service worker sert le cache en
// priorité au lancement (cf. service-worker.js), un reload() classique ne
// ferait que réafficher la même page déjà en cache si elle est bloquée/figée
// — sans jamais toucher le réseau. Le marqueur _swrefresh force le service
// worker à ignorer le cache pour CETTE navigation précise et à attendre une
// réponse fraîche du serveur (avec son propre filet de récupération si le
// serveur ne répond pas). Nettoyé de l'URL visible juste après, plus bas.
function forceFullPageRefresh() {
  try {
    const url = new URL(window.location.href);
    url.searchParams.set("_swrefresh", "1");
    window.location.replace(url.toString());
  } catch (error) {
    window.location.reload();
  }
}
window.forceFullPageRefresh = forceFullPageRefresh;

(function stripSwRefreshMarkerFromUrl() {
  try {
    const url = new URL(window.location.href);
    if (!url.searchParams.has("_swrefresh")) return;
    url.searchParams.delete("_swrefresh");
    window.history.replaceState({}, "", url.pathname + url.search + url.hash);
  } catch (error) {}
})();

(function initOffscreenAnimationPause() {
  const PAUSE_CLASS = 'agon-anim-paused';
  const SELECTORS = [
    '#agon-tag-trends-section',
    '#agon-cloud-loading-spinner',
    '.agon-cloud-loading',
    '.scroll-arrows',
    '.ranking-gain-box',
    '.debate-card-trend-badge',
    '.debate-card-new-badge',
    '.ai-card-badge-inner',
    '.theme-carousel-next-hint',
    '.theme-carousel-prev-hint',
    '.index-social-loading-placeholder',
    '.index-social-loading-placeholder-box',
    '.voice-stepper',
    '.my-argument-chip-stepper'
  ];

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(e => e.target.classList.toggle(PAUSE_CLASS, !e.isIntersecting));
  }, { rootMargin: '0px' });

  const observe = (root) => {
    SELECTORS.forEach(sel => root.querySelectorAll(sel).forEach(el => observer.observe(el)));
  };

  observe(document);

  let _mutTimer = null;
  const _pendingNodes = [];
  const _flushMutations = () => {
    _mutTimer = null;
    const nodes = _pendingNodes.splice(0);
    nodes.forEach(node => {
      SELECTORS.forEach(sel => {
        if (node.matches?.(sel)) observer.observe(node);
        node.querySelectorAll?.(sel).forEach(el => observer.observe(el));
      });
    });
  };
  new MutationObserver((mutations) => {
    mutations.forEach(({ addedNodes }) => {
      addedNodes.forEach(node => { if (node.nodeType === 1) _pendingNodes.push(node); });
    });
    if (!_mutTimer) _mutTimer = setTimeout(_flushMutations, 200);
  }).observe(document.body, { childList: true, subtree: false });

  // Observer ciblé sur les conteneurs de cartes (contenu dynamique)
  const _carouselObserver = new MutationObserver((mutations) => {
    mutations.forEach(({ addedNodes }) => {
      addedNodes.forEach(node => { if (node.nodeType === 1) _pendingNodes.push(node); });
    });
    if (!_mutTimer) _mutTimer = setTimeout(_flushMutations, 200);
  });
  const _observeCarousels = () => {
    document.querySelectorAll('.theme-horizontal-inner, .debates-section, #arguments-a, #arguments-b, #arguments-unified').forEach(el => {
      _carouselObserver.observe(el, { childList: true, subtree: true });
    });
  };
  _observeCarousels();
  setTimeout(_observeCarousels, 2000);

  // Stoppe toutes les animations quand la page passe en arrière-plan (onglet caché, écran éteint)
  document.addEventListener('visibilitychange', () => {
    document.body.classList.toggle(PAUSE_CLASS, document.hidden);
  });
})();

(function initAgonStartupLoader() {
  const loader = document.getElementById("agon-startup-loader");
  if (!loader) return;

  try { history.scrollRestoration = 'manual'; } catch (_) {}

  window.scrollTo(0, 0);

  const wait = function(ms) { return new Promise(function(r) { setTimeout(r, ms); }); };
  const waitForPaint = function() {
    return new Promise(function(resolve) {
      requestAnimationFrame(function() {
        requestAnimationFrame(resolve);
      });
    });
  };

  const waitForLineAnimationEnd = function(line) {
    if (!line) return Promise.resolve();
    return new Promise(function(resolve) {
      let done = false;
      const finish = function() {
        if (done) return;
        done = true;
        line.removeEventListener('animationend', finish);
        resolve();
      };
      line.addEventListener('animationend', finish);
      setTimeout(finish, 900);
    });
  };

  const playStartupLine = async function(line, holdAfterAnimationMs) {
    if (!line) return;
    await waitForPaint();
    if (!line.classList.contains('is-playing')) {
      window.__agonStartupLineStartedAt = window.performance && window.performance.now ? window.performance.now() : Date.now();
      line.classList.add('is-playing');
    }

    const startedAt = Number(window.__agonStartupLineStartedAt || 0);
    const now = window.performance && window.performance.now ? window.performance.now() : Date.now();
    const elapsed = startedAt ? Math.max(0, now - startedAt) : 0;

    if (elapsed < 1300) {
      await waitForLineAnimationEnd(line);
    }

    await wait(Math.max(0, holdAfterAnimationMs - elapsed));
  };

  let introSequenceDone = false;
  let contentReady = false;
  let fontsReady = false;
  let hidden = false;

  function tryHide() {
    if (hidden || !introSequenceDone || !contentReady || !fontsReady) return;
    hidden = true;
    try { window.scrollTo(0, 0); document.documentElement.scrollTop = 0; document.body.scrollTop = 0; } catch (_) {}
    loader.classList.add('is-hiding');
    // agon-startup-active (qui masque barre basse + pastille "Autres actus" +
    // flèches flottantes, cf. CSS critique d'index.html) n'est retirée qu'une
    // fois le loader réellement parti : pendant le fondu, WebKit (PWA iPhone)
    // ne peint pas la couche fixed du loader dans les ~60px du bas — des
    // éléments réaffichés à cet instant y apparaîtraient sous l'animation.
    setTimeout(function() {
      document.documentElement.classList.remove('agon-startup-active');
      if (loader.parentNode) loader.parentNode.removeChild(loader);
    }, 500);
  }

  // Condition contenu : le feed index doit avoir rendu ses cartes.
  window.addEventListener('agon:feed-ready', function() {
    contentReady = true;
    tryHide();
  }, { once: true });

  const markFontsReady = function() {
    fontsReady = true;
    tryHide();
  };
  if (document.fonts && document.fonts.ready) {
    Promise.race([
      document.fonts.ready,
      wait(1800)
    ]).then(markFontsReady).catch(markFontsReady);
  } else {
    setTimeout(markFontsReady, 500);
  }

  // Filet de sécurité absolu
  setTimeout(function() {
    if (hidden) return;
    hidden = true;
    document.documentElement.classList.remove('agon-startup-active');
    if (loader.parentNode) loader.parentNode.removeChild(loader);
  }, 10000);

  async function runIntroSequence() {
    // Pause sur le logo avant les messages
    if (window.__agonStartupInlineStarted !== true) {
      await wait(400);
    }

    await playStartupLine(loader.querySelector('.agon-startup-line-1'), 1600);

    introSequenceDone = true;
    tryHide();
  }

  runIntroSequence().catch(function() {
    introSequenceDone = true;
    tryHide();
  });
})();

// Accès localStorage/sessionStorage robustes (private browsing, quota plein, Safari ITP)
function lsGet(key) { try { return localStorage.getItem(key); } catch { return null; } }
function lsSet(key, val) { try { localStorage.setItem(key, String(val)); } catch {} }
function lsRemove(key) { try { localStorage.removeItem(key); } catch {} }

const PUSH_INVITE_LAST_SHOWN_KEY = "pushInviteLastShownAt";
const PUSH_INVITE_DISMISSED_KEY = "pushInviteDismissed";
const PUSH_SUBSCRIBED_KEY = "pushSubscribed";
const PUSH_VAPID_PUBLIC_KEY_STORAGE_KEY = "pushVapidPublicKey";
const PUSH_INVITE_COOLDOWN_MS = 24 * 60 * 60 * 1000;
// Empêche la fenêtre "Ton score a évolué" (showScoreChangeNotification) et
// l'invite aux notifications push (showPushInvite) de s'afficher coup sur
// coup (pénible pour l'utilisateur) : chacune enregistre son horodatage,
// l'autre vérifie qu'aucune des deux n'est apparue dans les 5 dernières
// minutes avant de s'afficher à son tour.
const SCORE_CHANGE_NOTIFICATION_LAST_SHOWN_KEY = "agon_score_change_notif_last_shown_at";
const SCORE_CHANGE_PUSH_INVITE_QUIET_WINDOW_MS = 5 * 60 * 1000;
let pushInviteToastEl = null;
let pushInviteEnablePending = false;
let pushSubscriptionSyncPromise = null;

// Nettoie la clé dismissed corrompue par l'ancien bug (iOS "denied" par défaut)
try {
  if (lsGet(PUSH_INVITE_DISMISSED_KEY) === "1" && lsGet(PUSH_SUBSCRIBED_KEY) !== "1") {
    lsRemove(PUSH_INVITE_DISMISSED_KEY);
  }
} catch {}

// Capture globale (toutes les pages) du prompt d'installation Android/Chrome ;
// consommé par shouldShowPushInvite et window.triggerAndroidInstall (index.html)
window.deferredInstallPrompt = window.deferredInstallPrompt || null;
window.addEventListener("beforeinstallprompt", (e) => {
  e.preventDefault();
  window.deferredInstallPrompt = e;
  ["install-pwa-btn", "install-pwa-btn-desktop"].forEach((id) => {
    const btn = document.getElementById(id);
    if (btn) btn.style.display = "flex";
  });
});

// Dès que l'installation se termine (Android/Chrome), on confirme et on guide
// l'ouverture : aucune API web ne permet de lancer l'app installée automatiquement.
// (Safari iOS n'émet pas cet événement : la modale d'instructions reste le guide.)
window.addEventListener("appinstalled", () => {
  window.deferredInstallPrompt = null;
  ["install-pwa-btn", "install-pwa-btn-desktop"].forEach((id) => {
    const btn = document.getElementById(id);
    if (btn) btn.style.display = "none";
  });
  ["install-modal-overlay", "agon-install-modal-fallback"].forEach((id) => {
    const modal = document.getElementById(id);
    if (modal) modal.style.display = "none";
  });

  let overlay = document.getElementById("agon-install-success-overlay");
  if (!overlay) {
    overlay = document.createElement("div");
    overlay.id = "agon-install-success-overlay";
    overlay.className = "install-modal-overlay";
    overlay.innerHTML = `
      <div class="install-modal" onclick="event.stopPropagation()">
        <div class="install-modal-brand">
          <img src="/icon-192-optimized.png" alt="" class="install-modal-app-icon">
        </div>
        <h3 class="install-modal-title">Agôn est installé&nbsp;!</h3>
        <div class="install-modal-section">
          <p class="install-modal-text">L'icône <strong>Agôn</strong> vient d'être ajoutée à ton écran d'accueil. Appuie dessus pour ouvrir l'application en plein écran.</p>
        </div>
        <button class="install-modal-android-btn" type="button" style="display:flex"
          onclick="document.getElementById('agon-install-success-overlay').style.display='none';document.body.style.overflow='';">
          Compris
        </button>
      </div>`;
    overlay.addEventListener("click", (e) => {
      if (e.target === overlay) {
        overlay.style.display = "none";
        document.body.style.overflow = "";
      }
    });
    document.body.appendChild(overlay);
  }
  overlay.style.display = "flex";
  document.body.style.overflow = "hidden";
});

function isMobilePushInviteSurface() {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
    return false;
  }

  return window.matchMedia("(max-width: 768px)").matches
    || window.matchMedia("(display-mode: standalone)").matches;
}

function browserCanUsePushNotifications() {
  return typeof window !== "undefined"
    && "Notification" in window
    && "serviceWorker" in navigator
    && "PushManager" in window;
}

function browserHasNotificationSurface() {
  return typeof window !== "undefined"
    && "Notification" in window
    && "serviceWorker" in navigator;
}

function isIOSDevice() {
  const ua = navigator.userAgent || "";
  return /iPhone|iPad|iPod/i.test(ua) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
}

function isStandaloneMode() {
  if (window.matchMedia("(display-mode: standalone)").matches || !!window.navigator.standalone) return true;
  if (document.body && document.body.classList.contains("is-standalone")) return true;
  try {
    if (window !== window.top) {
      if (!!window.top.navigator.standalone) return true;
      if (window.top.matchMedia("(display-mode: standalone)").matches) return true;
      if (window.parent.document.body.classList.contains("is-standalone")) return true;
    }
  } catch {}
  return false;
}

if (isStandaloneMode()) {
  document.documentElement.classList.add("is-standalone");
  document.body.classList.add("is-standalone");
}

// Alignement du dock flottant bas débat (retour/fermeture, refresh, compteur
// de voix) : voir le bloc CSS "Dock flottant bas débat unifié".
// --agon-dock-lift : dégagement au-dessus du bord bas visible. 0 en Safari
//   (barre d'outils) et sur les vieux iPhones PWA au viewport tronqué
//   (screen.height - innerHeight >> 0 en standalone) ; sinon safe-area.
//   Calculé dans le document parent, hérité tel quel par l'iframe du modal.
// --agon-embedded-bottom-ext : débordement de l'iframe du modal sous le
//   viewport parent (bottom négatif posé par le parent pour la safe-area).
(function initAgonDockAlignment() {
  const root = document.documentElement;
  let topWin = window;
  try { if (window.top && window.top.document) topWin = window.top; } catch {}
  const isEmbedded = topWin !== window;

  let envProbe = null;
  const readEnvBottom = () => {
    if (!envProbe) {
      envProbe = document.createElement("div");
      envProbe.setAttribute("aria-hidden", "true");
      envProbe.style.cssText = "position:fixed;left:0;bottom:0;width:0;height:0;padding-bottom:env(safe-area-inset-bottom,0px);visibility:hidden;pointer-events:none;z-index:-1;";
      (document.body || root).appendChild(envProbe);
    }
    return Math.max(0, Math.round(parseFloat(getComputedStyle(envProbe).paddingBottom) || 0));
  };

  const applied = { lift: null, ext: null };
  const update = () => {
    let lift = 0;
    let ext = 0;
    try {
      if (isEmbedded) {
        ext = Math.max(0, Math.round((Number(window.innerHeight) || 0) - (Number(topWin.innerHeight) || 0)));
        const inherited = parseFloat(topWin.document.documentElement.style.getPropertyValue("--agon-dock-lift"));
        lift = Number.isFinite(inherited) ? Math.max(0, Math.round(inherited)) : 0;
      } else if (isStandaloneMode()) {
        const portrait = (Number(window.innerHeight) || 0) >= (Number(window.innerWidth) || 0);
        const screenAlong = portrait
          ? Math.max(Number(screen.height) || 0, Number(screen.width) || 0)
          : Math.min(Number(screen.height) || 0, Number(screen.width) || 0);
        const truncated = screenAlong > 0 && screenAlong - (Number(window.innerHeight) || 0) > 20;
        if (!truncated) lift = readEnvBottom();
      }
    } catch {}
    if (applied.lift === lift && applied.ext === ext) return;
    applied.lift = lift;
    applied.ext = ext;
    root.style.setProperty("--agon-dock-lift", `${lift}px`);
    root.style.setProperty("--agon-embedded-bottom-ext", `${ext}px`);
  };

  update();
  window.addEventListener("resize", update);
  window.addEventListener("orientationchange", update);
  window.addEventListener("pageshow", update);
  window.visualViewport?.addEventListener("resize", update);
  if (isEmbedded) {
    // La valeur héritée peut changer côté parent après l'init de l'iframe.
    try {
      topWin.addEventListener("resize", update);
      topWin.visualViewport?.addEventListener("resize", update);
    } catch {}
  }
  // Au lancement standalone, iOS peut rapporter une hauteur provisoire (ex.
  // 802 puis 768 sur iPhone X/XS/11 Pro) sans émettre de resize : la détection
  // "viewport tronqué" figeait alors un lift erroné. Relances différées +
  // filet périodique (no-op grâce au garde applied si rien n'a bougé).
  setTimeout(update, 1000);
  setTimeout(update, 3000);
  setTimeout(update, 7000);
  // Anti-chauffe : dans un onglet navigateur classique (ni standalone, ni
  // iframe du modal), lift/ext restent à 0 — le filet 4s ne servait à rien
  // et empêchait l'idle profond. On le réserve aux contextes concernés.
  if (isEmbedded || isStandaloneMode()) {
    setInterval(update, 4000);
  }
})();

// Aligne le bouton retour (.mobile-back-button) et le badge de voix
// (#voices-float-badge) sur la même ligne, à cheval sur le bandeau bas de la
// page débat. Les deux vivent dans CE MÊME document (y compris embarqués
// dans l'iframe du modal, cf. .mobile-back-button réactivé côté CSS à la
// place du bouton de fermeture du parent) : une seule mesure directe de la
// position du bandeau suffit, plus besoin de synchroniser 2 documents avec
// des window.innerHeight différents et un état de barre Safari changeant.
(function initAgonDebateDockLineSync() {
  const DOCK_BUTTON_HEIGHT = 42;

  function sync() {
    if (!document.body || !document.body.classList.contains("page-debate") || window.innerWidth > 768) return;
    const nav = document.querySelector(".home-bottom-nav");
    if (!nav) return;

    const navTop = nav.getBoundingClientRect().top;
    const bottomOffset = Math.round(window.innerHeight - navTop - DOCK_BUTTON_HEIGHT / 2);
    document.documentElement.style.setProperty("--agon-dock-button-bottom", `${bottomOffset}px`);
  }

  sync();
  window.addEventListener("resize", sync);
  window.addEventListener("orientationchange", sync);
  window.visualViewport?.addEventListener("resize", sync);
  setTimeout(sync, 1000);
  setTimeout(sync, 3000);
  // Filet périodique réservé à la page débat (seule page où sync agit) : sur
  // les autres pages, ce réveil CPU chaque seconde empêchait l'idle profond
  // d'iOS et contribuait à la chauffe.
  if (document.body && document.body.classList.contains("page-debate")) {
    setInterval(sync, 1000);
  }
})();

// Flag purement local (posé dès la détection standalone, sans dépendre du
// réseau) : c'est lui qui doit déclencher le bandeau "ouvre l'app installée"
// ci-dessous. Le posait auparavant sur "appInstallPinged", qui n'est fixé que
// si le ping serveur réussit — un aléa réseau au lancement de l'app suffisait
// alors à empêcher le bandeau de s'afficher pour toujours sur cet appareil.
if (isStandaloneMode() && lsGet("agonStandaloneSeen") !== "1") {
  lsSet("agonStandaloneSeen", "1");
}

// Ping serveur (stats d'installation) : indépendant du flag ci-dessus, peut
// échouer/réessayer sans jamais affecter l'affichage du bandeau.
if (isStandaloneMode() && lsGet("appInstallPinged") !== "1") {
  fetch(API + "/users/mark-app-installed", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ legacyKey: getKey() })
  }).then((response) => {
    if (response.ok) lsSet("appInstallPinged", "1");
  }).catch(() => {});
}

// Bandeau "ouvre l'app installée" : aucune API web ne permet de relancer une
// PWA automatiquement (ni sur iOS ni sur Android sans wrapper natif), donc on
// se contente d'un rappel visuel quelques secondes quand ce navigateur a déjà
// tourné en standalone (flag posé ci-dessus) mais qu'on navigue hors standalone.
const OPEN_APP_BANNER_LAST_SHOWN_KEY = "openAppBannerLastShownAt";
const OPEN_APP_BANNER_COOLDOWN_MS = 24 * 60 * 60 * 1000;

function maybeShowOpenAppBanner() {
  // ?debugFlags=1 (insensible à la casse) : affiche l'état réel des flags via
  // alert() — diagnostic terrain sans outils de développement (utile sur iOS
  // Safari où le storage peut ne pas se comporter comme sur Android Chrome).
  if (/(?:^|[?&])debugflags=1(?:&|$)/i.test(location.search)) {
    alert(
      "agonStandaloneSeen: " + lsGet("agonStandaloneSeen") +
      "\nappInstallPinged: " + lsGet("appInstallPinged") +
      "\nopenAppBannerLastShownAt: " + lsGet(OPEN_APP_BANNER_LAST_SHOWN_KEY) +
      "\nisStandaloneMode(): " + isStandaloneMode() +
      "\nnavigator.standalone: " + window.navigator.standalone +
      "\ndisplay-mode standalone: " + window.matchMedia("(display-mode: standalone)").matches
    );
  }

  // ?debugBanner=1 (insensible à la casse) : force l'affichage pour vérifier
  // isolément le rendu visuel, sans dépendre des flags standalone/cooldown.
  const forceDebug = /(?:^|[?&])debugbanner=1(?:&|$)/i.test(location.search);
  if (forceDebug) {
    renderOpenAppBanner();
    return;
  }

  if (isStandaloneMode() || window !== window.top) return;

  const lastShown = Number(lsGet(OPEN_APP_BANNER_LAST_SHOWN_KEY) || 0);
  if (lastShown && Date.now() - lastShown < OPEN_APP_BANNER_COOLDOWN_MS) return;

  // Cas direct : ce navigateur a déjà tourné en standalone (Android/Chrome,
  // où PWA et navigateur partagent le même stockage).
  if (lsGet("agonStandaloneSeen") === "1") {
    lsSet(OPEN_APP_BANNER_LAST_SHOWN_KEY, String(Date.now()));
    renderOpenAppBanner();
    return;
  }

  // Cas iOS : Safari et la PWA ont des stockages séparés, le flag local
  // n'existe que côté PWA. Mais la PWA hérite de la clé anonyme copiée depuis
  // Safari à l'installation : on demande donc au serveur si cette clé est
  // marquée app_installed_at (cf. /api/users/app-installed). Vérification au
  // plus une fois par 24h pour ne pas interroger le serveur à chaque page.
  if (!window.matchMedia?.("(max-width: 768px)")?.matches) return;
  const checkedAt = Number(lsGet("appInstalledCheckedAt") || 0);
  if (checkedAt && Date.now() - checkedAt < OPEN_APP_BANNER_COOLDOWN_MS) return;
  lsSet("appInstalledCheckedAt", String(Date.now()));
  fetch(API + "/users/app-installed?legacyKey=" + encodeURIComponent(getKey()))
    .then((response) => (response.ok ? response.json() : null))
    .then((data) => {
      if (!data || !data.installed) return;
      // Mémorisé : les prochains passages prennent le cas direct sans requête.
      lsSet("agonStandaloneSeen", "1");
      lsSet(OPEN_APP_BANNER_LAST_SHOWN_KEY, String(Date.now()));
      renderOpenAppBanner();
    })
    .catch(() => {});
}

function renderOpenAppBanner() {
  if (!document.getElementById("agon-open-app-banner-styles")) {
    const style = document.createElement("style");
    style.id = "agon-open-app-banner-styles";
    style.textContent = `
      .agon-open-app-banner {
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        z-index: 9999;
        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;
        gap: 6px;
        padding: 14px 42px 14px 16px;
        padding-top: calc(14px + env(safe-area-inset-top, 0px));
        background: #16181d;
        color: #fff;
        font-size: 14px;
        box-shadow: 0 2px 10px rgba(0,0,0,.25);
        transform: translateY(-100%);
        transition: transform .35s ease;
      }
      .agon-open-app-banner.agon-open-app-banner-visible { transform: translateY(0); }
      .agon-open-app-banner img { width: 28px; height: 28px; border-radius: 7px; }
      .agon-open-app-banner span { line-height: 1.35; }
      .agon-open-app-banner-link {
        background: none;
        border: none;
        color: #fff;
        text-decoration: underline;
        font-weight: 600;
        font-size: 14px;
        padding: 2px 0;
        cursor: pointer;
      }
      .agon-open-app-banner-close {
        position: absolute;
        top: calc(8px + env(safe-area-inset-top, 0px));
        right: 8px;
        background: none;
        border: none;
        color: #9aa0aa;
        font-size: 22px;
        line-height: 1;
        padding: 4px;
        cursor: pointer;
      }
    `;
    document.head.appendChild(style);
  }

  const banner = document.createElement("div");
  banner.className = "agon-open-app-banner";
  banner.innerHTML = `
    <button type="button" class="agon-open-app-banner-close" aria-label="Fermer">&times;</button>
    <img src="/icon-192-optimized.png" alt="">
    <span>Utilise l'app Agôn déjà installée sur ton mobile pour retrouver tes contributions.</span>
    <button type="button" class="agon-open-app-banner-link">Comment l'ouvrir&nbsp;?</button>
  `;
  document.body.appendChild(banner);

  const hide = () => {
    banner.classList.remove("agon-open-app-banner-visible");
    setTimeout(() => banner.remove(), 400);
  };

  banner.querySelector(".agon-open-app-banner-close").addEventListener("click", hide);
  banner.querySelector(".agon-open-app-banner-link").addEventListener("click", showOpenAppHowToModal);
  requestAnimationFrame(() => banner.classList.add("agon-open-app-banner-visible"));
  // Pas de disparition automatique : seul le bouton de fermeture masque le bandeau,
  // pour laisser le temps de lire et de cliquer sur "Comment l'ouvrir ?".
}

// Rappel des étapes pour ouvrir l'app installée : aucune API web ne permet de
// la relancer depuis un lien (ni iOS ni Android sans wrapper natif), donc le
// lien du bandeau ouvre ces instructions plutôt qu'une tentative de lancement.
function showOpenAppHowToModal() {
  let overlay = document.getElementById("agon-open-app-howto-overlay");
  if (!overlay) {
    overlay = document.createElement("div");
    overlay.id = "agon-open-app-howto-overlay";
    overlay.className = "install-modal-overlay";
    overlay.innerHTML = `
      <div class="install-modal" onclick="event.stopPropagation()">
        <div class="install-modal-brand">
          <img src="/icon-192-optimized.png" alt="" class="install-modal-app-icon">
        </div>
        <h3 class="install-modal-title">Ouvrir l'app Agôn</h3>
        <div class="install-modal-section">
          <p class="install-modal-text">Aucun lien ne peut lancer l'app installée depuis le navigateur. Va sur ton <strong>écran d'accueil</strong> et appuie sur l'icône <strong>Agôn</strong> pour l'ouvrir en plein écran.</p>
        </div>
        <button class="install-modal-android-btn" type="button" style="display:flex">Compris</button>
      </div>`;
    const close = () => {
      overlay.style.display = "none";
      document.body.style.overflow = "";
    };
    overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
    overlay.querySelector(".install-modal-android-btn").addEventListener("click", close);
    document.body.appendChild(overlay);
  }
  overlay.style.display = "flex";
  document.body.style.overflow = "hidden";
}

maybeShowOpenAppBanner();

// Widget de score percentile (voix reçues / notes IA), injecté dans la topbar
// de toutes les pages (.topbar-inner, présent sur les 8 templates). N'affiche
// rien tant que l'utilisateur n'a pas au moins un score (aucune idée postée /
// aucune idée notée par l'IA pour l'instant).
// Number(null) vaut 0 en JS (piège classique) : un champ serveur explicitement
// `null` (pas de score) se faisait donc lire comme un vrai score de 0 par
// `Number.isFinite(Number(x)) ? Number(x) : null`, qui ne filtre que
// undefined/NaN/chaînes invalides, pas null. Résultat : "Top 0%" s'affichait
// pour des comptes n'ayant jamais rien publié. Ce helper distingue explicitement
// "absent" de "zéro".
function numOrNull(value) {
  if (value === null || value === undefined) return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

// Affichage FR (virgule) d'un pourcentage borné à 1 décimale (0,1 % / 99,9 %
// aux extrêmes, cf. buildPercentileScoreMap côté serveur).
function formatPct(n) {
  if (n === null || n === undefined || !Number.isFinite(Number(n))) return "";
  return Number(n).toLocaleString("fr-FR", { minimumFractionDigits: 0, maximumFractionDigits: 1 });
}

// Icône du score Logos : volute grecque (spirale) en SVG inline — pas
// d'équivalent dans Font Awesome. Le wrapper <i> conserve les styles
// existants qui ciblent les balises i (couleur, font-size → taille 1em).
const AGON_LOGOS_ICON = '<i class="agon-logos-icon" aria-hidden="true"><svg viewBox="2 0 21 21" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M12 11a1 1 0 0 1 1 1a2 2 0 0 1-2 2a3 3 0 0 1-3-3a4 4 0 0 1 4-4a5 5 0 0 1 5 5a6 6 0 0 1-6 6a7 7 0 0 1-7-7a8 8 0 0 1 8-8a9 9 0 0 1 9 9"/></svg></i>';

function renderUserScoreWidget(data) {
  const topbar = document.querySelector(".topbar");
  const topbarInner = document.querySelector(".topbar-inner");
  const brandBlock = document.querySelector(".home-brand-block");
  const brandMain = document.querySelector(".home-brand-main");
  if (!topbar || document.querySelector(".agon-user-score-widget")) return;

  const votesScoreRaw = numOrNull(data?.votesScore);
  const notesScoreRaw = numOrNull(data?.notesScore);
  const gnosisScoreRaw = numOrNull(data?.gnosisScore);
  // 1 décimale (pas Math.round entier) : préserve les bornes 0,1 / 99,9 posées
  // côté serveur pour les extrêmes, sinon Math.round(0.1) = 0 les efface.
  const votesScore = votesScoreRaw === null ? null : Math.round(votesScoreRaw * 10) / 10;
  const notesScore = notesScoreRaw === null ? null : Math.round(notesScoreRaw * 10) / 10;
  const gnosisScore = gnosisScoreRaw === null ? null : Math.round(gnosisScoreRaw * 10) / 10;
  const tierLabel = String(data?.tierLabel || "").trim();
  const tier = numOrNull(data?.tier);
  const tierCount = numOrNull(data?.tierCount);
  const gnosisTierLabel = String(data?.gnosisTierLabel || "").trim();
  const gnosisTier = numOrNull(data?.gnosisTier);
  const gnosisTierCount = numOrNull(data?.gnosisTierCount);
  const stats = {
    votesTotalUsers: numOrNull(data?.votesTotalUsers),
    notesTotalUsers: numOrNull(data?.notesTotalUsers),
    gnosisTotalUsers: numOrNull(data?.gnosisTotalUsers),
    votesTierUsers: numOrNull(data?.votesTierUsers),
    notesTierUsers: numOrNull(data?.notesTierUsers),
    gnosisTierUsers: numOrNull(data?.gnosisTierUsers),
    votesValue: numOrNull(data?.votesValue),
    notesValue: numOrNull(data?.notesValue),
    gnosisAnswered: numOrNull(data?.gnosisAnswered),
    gnosisCorrect: numOrNull(data?.gnosisCorrect)
  };

  maybeNotifyScoreChange(votesScore, notesScore, gnosisScore, () =>
    showUserScoreModal(votesScore, notesScore, gnosisScore, tierLabel, stats, tier, tierCount, gnosisTierLabel, gnosisTier, gnosisTierCount)
  );

  if (!document.getElementById("agon-user-score-styles")) {
    const style = document.createElement("style");
    style.id = "agon-user-score-styles";
    style.textContent = `
      .agon-user-score-row {
        display: flex;
        justify-content: center;
        padding: 0 12px 6px;
      }
      .agon-user-score-widget {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 4px 12px;
        border-radius: 999px;
        background: #fff;
        color: #111827;
        border: 1px solid #111827;
        font-size: 11px;
        font-weight: 700;
        white-space: nowrap;
        text-decoration: none;
        max-width: 100%;
        overflow: hidden;
        text-overflow: ellipsis;
      }
      .agon-user-score-widget i { font-size: 10px; color: #9cc3f0; }
      .agon-user-score-widget-inline {
        flex: 0 0 auto;
      }
      .agon-user-score-anchor {
        position: relative;
        overflow: visible;
      }
      .agon-user-score-widget-logo-overlay {
        position: absolute;
        left: 50%;
        bottom: 12px;
        z-index: 18;
        transform: translateX(-50%);
        justify-content: center;
        box-shadow: 0 6px 16px rgba(15, 23, 42, 0.18);
      }
      body.page-home .agon-user-score-widget-logo-overlay,
      body.page-home-mobile .agon-user-score-widget-logo-overlay,
      body.page-tribunes .agon-user-score-widget-logo-overlay,
      body.page-debate .agon-user-score-widget-logo-overlay {
        max-width: min(210px, calc(100vw - 120px));
      }
      /* Avec les 3 scores (Rhetor + Logos + Gnosis), le texte dépasse le
         plafond ci-dessus et se fait tronquer (ellipsis) — plafond élargi
         uniquement pour ce cas, les badges à 1-2 scores restent inchangés. */
      body.page-home .agon-user-score-widget-logo-overlay.agon-user-score-widget-triple,
      body.page-home-mobile .agon-user-score-widget-logo-overlay.agon-user-score-widget-triple,
      body.page-tribunes .agon-user-score-widget-logo-overlay.agon-user-score-widget-triple,
      body.page-debate .agon-user-score-widget-logo-overlay.agon-user-score-widget-triple {
        max-width: min(320px, calc(100vw - 40px));
      }
      @media (max-width: 768px) {
        /* Variante "inline" (toutes les pages hors accueil/tribunes/débat,
           qui utilisent la variante superposée au logo ci-dessous) : simple
           décalage vertical, sans toucher au flux ni au transform horizontal
           de la variante superposée (sélecteur exclu explicitement). */
        .agon-user-score-widget:not(.agon-user-score-widget-logo-overlay) {
          transform: translateY(2px);
        }
        body.page-home-mobile .agon-user-score-widget-logo-overlay,
        body.page-tribunes .agon-user-score-widget-logo-overlay,
        body.page-debate .agon-user-score-widget-logo-overlay {
          bottom: 10px;
        }
      }
      @media (max-width: 480px) {
        .agon-user-score-widget {
          font-size: 9.5px;
          padding: 3px 9px;
        }
        body.page-home-mobile .agon-user-score-widget-logo-overlay,
        body.page-tribunes .agon-user-score-widget-logo-overlay,
        body.page-debate .agon-user-score-widget-logo-overlay {
          bottom: 9px;
          transform: translateX(-50%);
          max-width: min(168px, calc(100vw - 116px));
          font-size: 8.5px;
          padding: 2px 7px;
          gap: 4px;
        }
        body.page-home-mobile .agon-user-score-widget-logo-overlay i,
        body.page-tribunes .agon-user-score-widget-logo-overlay i,
        body.page-debate .agon-user-score-widget-logo-overlay i {
          font-size: 8px;
        }
        body.page-home-mobile .agon-user-score-widget-logo-overlay.agon-user-score-widget-triple,
        body.page-tribunes .agon-user-score-widget-logo-overlay.agon-user-score-widget-triple,
        body.page-debate .agon-user-score-widget-logo-overlay.agon-user-score-widget-triple {
          max-width: min(260px, calc(100vw - 40px));
        }
      }
    `;
    document.head.appendChild(style);
  }

  const widget = document.createElement("a");
  // Les 3 scores existent toujours désormais (pire note tant qu'on n'a rien
  // posté/répondu, cf. USER_SCORE_EMPTY côté serveur) : toujours 3 valeurs,
  // toujours la variante large du badge.
  widget.className = "agon-user-score-widget agon-user-score-widget-triple";
  widget.href = "/mon-univers";
  widget.setAttribute("aria-label", "Mes scores");
  widget.addEventListener("click", (e) => {
    e.preventDefault();
    showUserScoreModal(votesScore, notesScore, gnosisScore, tierLabel, stats, tier, tierCount, gnosisTierLabel, gnosisTier, gnosisTierCount);
  });

  widget.innerHTML = [
    '<i class="fa-solid fa-bolt"></i>Top ' + formatPct(votesScore) + '% (Rhetor)',
    AGON_LOGOS_ICON + formatPct(notesScore) + '% (Logos)',
    '<i class="fa-solid fa-brain"></i>' + formatPct(gnosisScore) + '% (Gnosis)'
  ].join(' <span style="opacity:.5">-</span> ');

  const isDesktop = window.matchMedia("(min-width: 769px)").matches;
  // page-tribunes / page-debate : le bandeau de ces pages est une réplique
  // de celui de l'index (topbar dans un wrapper page-home/page-home-mobile),
  // le badge s'y place donc pareil, en overlay sur le logo.
  const isIndexPage = document.body.classList.contains("page-home")
    || document.body.classList.contains("page-home-mobile")
    || document.body.classList.contains("page-tribunes")
    || document.body.classList.contains("page-debate");
  if (isIndexPage && brandMain) {
    brandMain.classList.add("agon-user-score-anchor");
    widget.classList.add("agon-user-score-widget-logo-overlay");
    brandMain.appendChild(widget);
  } else if (isDesktop && brandBlock && topbarInner && brandBlock.parentElement === topbarInner) {
    // Desktop : en ligne juste après le logo, avant les icônes réseau / le
    // reste de la barre (flex:1 sur .home-brand-block pousse tout ce qui
    // suit contre le cluster de droite — donc "juste après" = collé au
    // cluster, entre le logo et les icônes réseau).
    widget.classList.add("agon-user-score-widget-inline");
    brandBlock.insertAdjacentElement("afterend", widget);
  } else {
    // Mobile : nouvelle ligne dédiée sous le logo, pour ne jamais chevaucher
    // le reste de la barre (menu, icônes) qui reste très compact sur mobile.
    // Insérée juste après .topbar-inner (pas à la fin de .topbar, qui peut
    // contenir d'autres blocs après — ex: admin-controls-row) pour rester
    // collée au logo au lieu de dériver plus bas dans la page.
    const row = document.createElement("div");
    row.className = "agon-user-score-row";
    row.appendChild(widget);
    if (topbarInner) topbarInner.insertAdjacentElement("afterend", row);
    else topbar.appendChild(row);
  }
}

// Fenêtre visible dès qu'un des 3 scores a changé depuis la dernière visite
// (comparaison à une valeur mémorisée en localStorage) — pas seulement le
// badge discret du bandeau, qu'on peut facilement ne pas remarquer.
// Aucune notification au tout premier chargement connu (pas de valeur de
// référence à comparer) : seulement à partir de la 2e visite, quand une
// évolution est réellement détectable.
const AGON_SCORE_CHANGE_BASELINE_KEY = "agon_last_known_scores";
function maybeNotifyScoreChange(votesScore, notesScore, gnosisScore, openDetail) {
  // Pas de valeur mémorisée (tout premier chargement connu) : traité comme
  // une base à null/null/null plutôt qu'un "rien à comparer, on ignore" —
  // un score qui apparaît pour la première fois (null -> une vraie valeur)
  // doit lui aussi déclencher la notification, pas seulement une évolution
  // entre deux valeurs déjà connues.
  let previous = { votesScore: null, notesScore: null, gnosisScore: null };
  try {
    const stored = JSON.parse(localStorage.getItem(AGON_SCORE_CHANGE_BASELINE_KEY) || "null");
    if (stored) previous = stored;
  } catch (e) {}
  try {
    localStorage.setItem(AGON_SCORE_CHANGE_BASELINE_KEY, JSON.stringify({ votesScore, notesScore, gnosisScore }));
  } catch (e) {}

  const changes = [];
  if (votesScore !== null && previous.votesScore !== votesScore) {
    changes.push({ icon: '<i class="fa-solid fa-bolt"></i>', label: "Rhetor", value: votesScore });
  }
  if (notesScore !== null && previous.notesScore !== notesScore) {
    changes.push({ icon: AGON_LOGOS_ICON, label: "Logos", value: notesScore });
  }
  if (gnosisScore !== null && previous.gnosisScore !== gnosisScore) {
    changes.push({ icon: '<i class="fa-solid fa-brain"></i>', label: "Gnosis", value: gnosisScore });
  }
  if (!changes.length) return;
  // Arrivée depuis une notification "ton idée a été notée par l'IA" (cf.
  // isAiScorePopupOverlayContext) : sa propre fenêtre détaillée va s'ouvrir
  // pour expliquer CETTE note précise — inutile d'empiler par-dessus la
  // notification générique du widget pour le même événement (le score global
  // vient justement de changer à cause de cette même note).
  if (typeof isAiScorePopupOverlayContext === "function" && isAiScorePopupOverlayContext()) return;
  showScoreChangeNotification(changes, openDetail);
}

function showScoreChangeNotification(changes, openDetail) {
  // Ne jamais s'afficher coup sur coup avec l'invite aux notifications push
  // (showPushInvite) — cf. SCORE_CHANGE_PUSH_INVITE_QUIET_WINDOW_MS.
  const pushInviteShownAt = Number(lsGet(PUSH_INVITE_LAST_SHOWN_KEY) || 0);
  if (pushInviteShownAt && Date.now() - pushInviteShownAt < SCORE_CHANGE_PUSH_INVITE_QUIET_WINDOW_MS) return;
  lsSet(SCORE_CHANGE_NOTIFICATION_LAST_SHOWN_KEY, String(Date.now()));

  // Le widget de score s'initialise à la fois sur la page hôte et dans
  // l'iframe /debate (cf. initUserScoreWidget, isDebateIframe) : sans ça,
  // chaque contexte crée sa propre fenêtre dans son propre document quand les
  // deux s'initialisent au même moment (ex. rechargement avec une arène
  // restaurée automatiquement dans l'iframe), et on voit 2 fenêtres empilées.
  // On pose toujours l'overlay dans le document le plus haut (même origine) :
  // les deux contextes convergent alors vers le même élément, le retrait de
  // l'"existing" ci-dessous garantit qu'il n'y en a jamais qu'un affiché.
  let topDoc = document;
  try { if (window.top && window.top.document) topDoc = window.top.document; } catch (e) {}

  const existing = topDoc.getElementById("agon-score-change-overlay");
  if (existing) existing.remove();

  const overlay = topDoc.createElement("div");
  overlay.id = "agon-score-change-overlay";
  overlay.className = "install-modal-overlay";
  overlay.style.display = "flex";
  const lines = changes
    .map((c) => '<p class="install-modal-text">' + c.icon + ' <strong>' + c.label + '</strong> — désormais Top ' + formatPct(c.value) + '%</p>')
    .join("");
  overlay.innerHTML =
    '<div class="install-modal" onclick="event.stopPropagation()">' +
    '<button class="install-modal-close" type="button" aria-label="Fermer" id="agon-score-change-close-btn"><i class="fa-solid fa-xmark"></i></button>' +
    '<h3 class="install-modal-title">Ton score a évolué</h3>' +
    lines +
    '<button class="install-modal-secondary-btn" type="button" id="agon-score-change-close-btn-bottom">Fermer</button>' +
    '</div>';
  const close = () => overlay.remove();
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
  overlay.querySelector("#agon-score-change-close-btn").addEventListener("click", close);
  overlay.querySelector("#agon-score-change-close-btn-bottom").addEventListener("click", close);
  topDoc.body.appendChild(overlay);
}

// Explique les 2 scores au clic sur le widget — noms empruntés à la rhétorique
// classique (Agôn = joute oratoire) : Rhetor pour les voix récoltées, Logos
// pour la qualité argumentative notée par l'IA.
function formatUserCount(n) {
  return Number.isFinite(n) ? n.toLocaleString("fr-FR") + (n > 1 ? " contributeurs" : " contributeur") : "";
}

function showUserScoreModal(votesScore, notesScore, gnosisScore, tierLabel, stats, tier, tierCount, gnosisTierLabel, gnosisTier, gnosisTierCount, initialTab) {
  // Même raisonnement que showScoreChangeNotification : le badge (et donc ce
  // clic) peut venir de l'iframe /debate, mais le détail doit toujours
  // s'afficher dans le document le plus haut pour rester cohérent avec la
  // notification qui a pu ouvrir ce détail (openDetail).
  let topDoc = document;
  try { if (window.top && window.top.document) topDoc = window.top.document; } catch (e) {}

  const existing = topDoc.getElementById("agon-user-score-overlay");
  if (existing) existing.remove();

  const overlay = topDoc.createElement("div");
  overlay.id = "agon-user-score-overlay";
  overlay.className = "install-modal-overlay";

  const s = stats || {};
  const tierRank = (Number.isFinite(tier) && Number.isFinite(tierCount)) ? (' (' + tier + '/' + tierCount + ')') : '';

  // Rhetor et Logos partagent le même palier (volume d'idées postées) mais
  // pas la même population (tout le monde n'a pas de note IA) : une ligne de
  // comptage par axe, chacune affichée dans l'onglet de son propre axe.
  const votesTierCountHint = (Number.isFinite(s.votesTierUsers) && Number.isFinite(s.votesTotalUsers))
    ? '<p class="install-modal-text install-modal-hint">Palier Rhetor : ' + formatUserCount(s.votesTierUsers) + ' · Tous paliers confondus : ' + formatUserCount(s.votesTotalUsers) + '</p>'
    : '';
  const notesTierCountHint = (Number.isFinite(s.notesTierUsers) && Number.isFinite(s.notesTotalUsers))
    ? '<p class="install-modal-text install-modal-hint">Palier Logos : ' + formatUserCount(s.notesTierUsers) + ' · Tous paliers confondus : ' + formatUserCount(s.notesTotalUsers) + '</p>'
    : '';
  const tierIntro = tierLabel
    ? '<h4 class="install-modal-platform"><i class="fa-solid fa-layer-group"></i> Ton palier' + tierRank + ' — ' + tierLabel + '</h4>' +
      '<p class="install-modal-text">Pour une comparaison juste, tu n\'es classé que parmi les contributeurs ayant posté un volume d\'idées similaire au tien.</p>'
    : '';

  // Palier propre à Gnosis (basé sur le nombre de questions répondues au QCM,
  // pas le nombre d'idées postées) : population différente de celle des 2
  // autres scores.
  const gnosisTierRank = (Number.isFinite(gnosisTier) && Number.isFinite(gnosisTierCount)) ? (' (' + gnosisTier + '/' + gnosisTierCount + ')') : '';
  const gnosisTierCountHint = (Number.isFinite(s.gnosisTierUsers) && Number.isFinite(s.gnosisTotalUsers))
    ? '<p class="install-modal-text install-modal-hint">Palier : ' + formatUserCount(s.gnosisTierUsers) + ' · Tous paliers confondus : ' + formatUserCount(s.gnosisTotalUsers) + '</p>'
    : '';
  const gnosisTierIntro = gnosisTierLabel
    ? '<h4 class="install-modal-platform"><i class="fa-solid fa-layer-group"></i> Ton palier Gnosis' + gnosisTierRank + ' — ' + gnosisTierLabel + '</h4>' +
      '<p class="install-modal-text">Classé parmi les contributeurs ayant répondu à un volume de questions similaire au tien.</p>'
    : '';

  // Chaque score a son propre onglet (clic sur Rhetor / Logos / Gnosis dans
  // le menu) plutôt que d'être tous empilés à la suite dans la modale. Les 3
  // scores existent toujours (pire note tant qu'on n'a rien posté/répondu,
  // cf. USER_SCORE_EMPTY côté serveur), donc toujours 3 onglets.
  const hasVotesScore = Number.isFinite(s.votesValue);
  const hasNotesScore = Number.isFinite(s.notesValue);
  const hasGnosisScore = Number.isFinite(s.gnosisCorrect) && Number.isFinite(s.gnosisAnswered);
  const votesValueLine = hasVotesScore
    ? '<p class="install-modal-text"><strong>' + s.votesValue.toLocaleString("fr-FR") + (s.votesValue > 1 ? ' voix reçues' : ' voix reçue') + '</strong> au total sur toutes tes idées.</p>'
    : '';
  const notesValueLine = hasNotesScore
    ? '<p class="install-modal-text"><strong>Moyenne de ' + s.notesValue.toLocaleString("fr-FR") + '/100</strong> sur tes idées notées par l\'IA.</p>'
    : '';
  const gnosisValueLine = hasGnosisScore
    ? '<p class="install-modal-text"><strong>' + s.gnosisCorrect.toLocaleString("fr-FR") + ' / ' + s.gnosisAnswered.toLocaleString("fr-FR") + ' bonnes réponses</strong> au QCM.</p>'
    : '';
  const votesExplanation = hasVotesScore
    ? 'Mesure les voix récoltées sur toutes tes idées. ' + formatPct(votesScore) + '% des contributeurs de ton palier ont reçu plus de voix que toi, ' + formatPct(100 - votesScore) + '% en ont reçu moins.'
    : '100 % des utilisateurs qui ont participé ont un meilleur score que toi, car tu n\'as pas encore publié d\'idée.';
  const notesExplanation = hasNotesScore
    ? 'Mesure la qualité moyenne de tes idées, notée par l\'IA. ' + formatPct(notesScore) + '% des contributeurs de ton palier ont une meilleure moyenne que toi, ' + formatPct(100 - notesScore) + '% ont une moyenne inférieure.'
    : '100 % des utilisateurs qui ont participé ont un meilleur score que toi, car aucune de tes idées n\'a encore été évaluée.';
  const gnosisExplanation = hasGnosisScore
    ? 'Mesure ta justesse au QCM. ' + formatPct(gnosisScore) + '% des contributeurs de ton palier ont une meilleure part de bonnes réponses que toi, ' + formatPct(100 - gnosisScore) + '% ont une part inférieure.'
    : '100 % des utilisateurs qui ont participé ont un meilleur score que toi, car tu n\'as pas encore répondu au QCM.';
  const tabs = [
    {
      key: "rhetor",
      icon: '<i class="fa-solid fa-bolt"></i>',
      label: "Rhetor",
      content:
        (hasVotesScore ? tierIntro + votesTierCountHint : '') +
        '<div class="install-modal-divider"></div>' +
        '<h4 class="install-modal-platform"><i class="fa-solid fa-bolt"></i> Score Rhetor — Top ' + formatPct(votesScore) + '%</h4>' +
        votesValueLine +
        '<p class="install-modal-text">' + votesExplanation + '</p>'
    },
    {
      key: "logos",
      icon: AGON_LOGOS_ICON,
      label: "Logos",
      content:
        (hasNotesScore ? tierIntro + notesTierCountHint : '') +
        '<div class="install-modal-divider"></div>' +
        '<h4 class="install-modal-platform">' + AGON_LOGOS_ICON + ' Score Logos — Top ' + formatPct(notesScore) + '%</h4>' +
        notesValueLine +
        '<p class="install-modal-text">' + notesExplanation + '</p>'
    },
    {
      key: "gnosis",
      icon: '<i class="fa-solid fa-brain"></i>',
      label: "Gnosis",
      content:
        (hasGnosisScore ? gnosisTierIntro + gnosisTierCountHint : '') +
        '<div class="install-modal-divider"></div>' +
        '<h4 class="install-modal-platform"><i class="fa-solid fa-brain"></i> Score Gnosis — Top ' + formatPct(gnosisScore) + '%</h4>' +
        gnosisValueLine +
        '<p class="install-modal-text">' + gnosisExplanation + '</p>'
    }
  ];

  const activeTabKey = tabs.some((t) => t.key === initialTab) ? initialTab : tabs[0].key;
  const tabButtons = tabs.map((t) =>
    '<button type="button" class="agon-score-tab' + (t.key === activeTabKey ? ' active' : '') + '" data-score-tab="' + t.key + '">' + t.icon + '<span>' + t.label + '</span></button>'
  ).join('');
  const tabPanels = tabs.map((t) =>
    '<div class="agon-score-tab-panel install-modal-section" data-score-tab="' + t.key + '"' + (t.key === activeTabKey ? '' : ' hidden') + '>' + t.content + '</div>'
  ).join('');
  const bodyHtml = '<div class="agon-score-tabs" role="tablist">' + tabButtons + '</div>' + tabPanels;

  overlay.innerHTML =
    '<div class="install-modal" onclick="event.stopPropagation()">' +
      '<button class="install-modal-close" type="button" aria-label="Fermer" id="agon-user-score-close-btn"><i class="fa-solid fa-xmark"></i></button>' +
      '<h3 class="install-modal-title">Tes scores</h3>' +
      bodyHtml +
      '<button class="install-modal-android-btn" type="button" style="display:flex">Compris</button>' +
    '</div>';

  overlay.querySelectorAll(".agon-score-tab").forEach((btn) => {
    btn.addEventListener("click", () => {
      const key = btn.dataset.scoreTab;
      overlay.querySelectorAll(".agon-score-tab").forEach((b) => b.classList.toggle("active", b === btn));
      overlay.querySelectorAll(".agon-score-tab-panel").forEach((panel) => {
        panel.hidden = panel.dataset.scoreTab !== key;
      });
    });
  });

  const close = () => {
    overlay.style.display = "none";
    topDoc.body.style.overflow = "";
  };
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
  overlay.querySelector(".install-modal-android-btn").addEventListener("click", close);
  overlay.querySelector("#agon-user-score-close-btn").addEventListener("click", close);
  topDoc.body.appendChild(overlay);
  overlay.style.display = "flex";
  topDoc.body.style.overflow = "hidden";
}

(function initUserScoreWidget() {
  // Le badge doit rester visible dans l'iframe de la page débat (mode iframe
  // mobile, cf. isIframeDebateLoadingOverlayContext) — son bandeau répliqué y
  // est réellement affiché à l'écran, contrairement aux autres iframes de
  // modales internes (notifications, contributions, création…) où le badge
  // resterait caché derrière le contenu et ferait doublon avec celui de la
  // page hôte.
  const isDebateIframe = location.pathname === "/debate" && window.self !== window.top;
  if (window !== window.top && !isDebateIframe) return;
  const key = getKey();
  if (!key) return;
  fetch(API + "/my-score?key=" + encodeURIComponent(key))
    .then((r) => (r.ok ? r.json() : null))
    .then((data) => { if (data) renderUserScoreWidget(data); })
    .then(renderAgonTimeWidget)
    .catch(() => {});
})();

// Compte à rebours de 60 min de bonne santé numérique, sous le badge de
// score dans le bandeau du haut. Mesure le temps actif cumulé (pas une
// horloge murale) : en pause dès qu'on quitte l'onglet/l'app, reprend sans
// repartir de zéro au retour — persisté par journée dans localStorage pour
// survivre aux navigations, aux nouveaux onglets et aux fermetures/réouvertures
// du site (pas de blocage à zéro une fois écoulé, juste un repère visuel qui
// passe au rouge dans les 10 dernières minutes).
const AGON_TIME_WIDGET_MINUTES = 60;
const AGON_TIME_WIDGET_WARNING_S = 10 * 60;
function renderAgonTimeWidget() {
  const scoreWidget = document.querySelector(".agon-user-score-widget");
  if (!scoreWidget || document.querySelector(".agon-time-widget")) return;

  const elapsedKey = "agon_time_widget_daily_v2";
  function getParisDayKey() {
    try {
      const parts = new Intl.DateTimeFormat("fr-FR", {
        timeZone: "Europe/Paris",
        year: "numeric",
        month: "2-digit",
        day: "2-digit"
      }).formatToParts(new Date());
      const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
      return values.year + "-" + values.month + "-" + values.day;
    } catch (e) {
      const now = new Date();
      return now.getFullYear() + "-" + String(now.getMonth() + 1).padStart(2, "0") + "-" + String(now.getDate()).padStart(2, "0");
    }
  }
  let activeDayKey = getParisDayKey();
  function readStoredElapsed() {
    try {
      const stored = JSON.parse(localStorage.getItem(elapsedKey) || "null");
      const elapsedMs = Number(stored?.elapsedMs);
      return stored?.dayKey === activeDayKey && Number.isFinite(elapsedMs) && elapsedMs > 0
        ? elapsedMs
        : 0;
    } catch (e) {
      return 0;
    }
  }
  let baseElapsedMs = readStoredElapsed();
  let resumedAt = Date.now();
  let running = !document.hidden;
  function currentElapsedMs() {
    return baseElapsedMs + (running ? Date.now() - resumedAt : 0);
  }
  function persistElapsed() {
    const elapsedMs = Math.max(currentElapsedMs(), readStoredElapsed());
    try { localStorage.setItem(elapsedKey, JSON.stringify({ dayKey: activeDayKey, elapsedMs })); } catch (e) {}
    return elapsedMs;
  }
  function resetIfNewDay() {
    const todayKey = getParisDayKey();
    if (todayKey === activeDayKey) return;
    activeDayKey = todayKey;
    baseElapsedMs = 0;
    resumedAt = Date.now();
    try { localStorage.setItem(elapsedKey, JSON.stringify({ dayKey: activeDayKey, elapsedMs: 0 })); } catch (e) {}
  }
  function pauseTimeWidget() {
    if (!running) return;
    baseElapsedMs += Date.now() - resumedAt;
    running = false;
    baseElapsedMs = persistElapsed();
  }
  function resumeTimeWidget() {
    if (running) return;
    resetIfNewDay();
    baseElapsedMs = Math.max(baseElapsedMs, readStoredElapsed());
    resumedAt = Date.now();
    running = true;
  }
  document.addEventListener("visibilitychange", () => { document.hidden ? pauseTimeWidget() : resumeTimeWidget(); });
  window.addEventListener("blur", pauseTimeWidget);
  window.addEventListener("focus", resumeTimeWidget);
  window.addEventListener("pagehide", pauseTimeWidget);

  if (!document.getElementById("agon-time-widget-styles")) {
    const style = document.createElement("style");
    style.id = "agon-time-widget-styles";
    style.textContent = `
      .agon-time-widget-anchor {
        position: relative;
        overflow: visible;
      }
      .agon-time-widget-logo-overlay {
        position: absolute;
        top: 4px;
        left: 50%;
        transform: translateX(-50%);
        z-index: 18;
        max-width: min(220px, calc(100vw - 40px));
      }
      @media (max-width: 768px) {
        .agon-time-widget-logo-overlay {
          top: -3px;
        }
      }
      .agon-time-widget {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 4px 12px;
        border-radius: 999px;
        background: transparent;
        color: #111827;
        border: none;
        font-size: 11px;
        font-weight: 700;
        white-space: nowrap;
        cursor: pointer;
      }
      .agon-time-widget i { font-size: 10px; color: #9cc3f0; }
      .agon-time-widget-warning { border-color: #d64545; color: #d64545; }
      .agon-time-widget-warning i { color: #d64545; }
      .agon-time-widget-expired {
        text-align: center;
      }
      @keyframes agon-time-widget-blink {
        0%, 100% { opacity: 1; }
        50% { opacity: 0.15; }
      }
      .agon-time-widget-blinking {
        animation: agon-time-widget-blink 0.4s ease-in-out 3;
      }
    `;
    document.head.appendChild(style);
  }

  const widget = document.createElement("button");
  widget.type = "button";
  widget.className = "agon-time-widget";
  widget.setAttribute("aria-label", "Temps passé sur agôn aujourd'hui");
  widget.innerHTML = '<i class="fa-regular fa-clock"></i><span></span>';
  widget.addEventListener("click", showAgonTimeWidgetExplanation);

  // Une fois les 60 min dépassées, le badge bascule sur un message d'alerte
  // et clignote 3 fois à chaque transition vers l'état "visible + dépassé"
  // (montage de la page déjà expirée, ou passage à 0 pendant que le badge
  // est déjà à l'écran, ou retour dans le viewport après en être sorti) —
  // état unifié pour ne jamais déclencher deux clignotements pour le même
  // "aperçu", sans pour autant bloquer quoi que ce soit.
  let expired = false;
  let visible = false;
  let wasBlinkActive = false;
  function maybeBlink() {
    const shouldBlink = expired && visible;
    if (shouldBlink && !wasBlinkActive) {
      widget.classList.remove("agon-time-widget-blinking");
      void widget.offsetWidth;
      widget.classList.add("agon-time-widget-blinking");
    }
    wasBlinkActive = shouldBlink;
  }
  function tick() {
    resetIfNewDay();
    const remaining = Math.max(0, AGON_TIME_WIDGET_MINUTES * 60 - Math.floor(currentElapsedMs() / 1000));
    const isExpired = remaining <= 0;
    if (isExpired) {
      widget.querySelector("span").textContent = "Attention à ta santé numérique !";
    } else {
      const mm = String(Math.floor(remaining / 60)).padStart(2, "0");
      const ss = String(remaining % 60).padStart(2, "0");
      widget.querySelector("span").textContent = mm + ":" + ss;
    }
    widget.classList.toggle("agon-time-widget-warning", remaining <= AGON_TIME_WIDGET_WARNING_S);
    widget.classList.toggle("agon-time-widget-expired", isExpired);
    expired = isExpired;
    maybeBlink();
    // Persisté à chaque tick (pas seulement à la pause) pour ne pas perdre
    // les dernières secondes actives si la page se ferme/navigue sans que
    // pagehide/blur n'ait le temps de se déclencher proprement.
    if (running) persistElapsed();
  }
  tick();
  setInterval(tick, 1000);

  if ("IntersectionObserver" in window) {
    new IntersectionObserver((entries) => {
      visible = entries[0].isIntersecting;
      maybeBlink();
    }).observe(widget);
  } else {
    visible = true;
    maybeBlink();
  }

  // Superposé sur le logo (en haut), comme le badge de score l'est déjà en
  // bas — en position absolute donc sans jamais pousser le logo ni changer
  // la hauteur du bandeau, quels que soient les marges/paddings autour du
  // logo sur telle ou telle page.
  const logoEl = document.querySelector(".home-logo");
  const anchor = logoEl ? logoEl.parentElement : null;
  if (anchor) {
    anchor.classList.add("agon-time-widget-anchor");
    widget.classList.add("agon-time-widget-logo-overlay");
    anchor.appendChild(widget);
  } else {
    document.querySelector(".topbar-inner")?.appendChild(widget);
  }
}

function showAgonTimeWidgetExplanation() {
  const existing = document.getElementById("agon-time-widget-overlay");
  if (existing) existing.remove();
  const overlay = document.createElement("div");
  overlay.id = "agon-time-widget-overlay";
  overlay.className = "install-modal-overlay";
  overlay.style.display = "flex";
  overlay.innerHTML =
    '<div class="install-modal" onclick="event.stopPropagation()">' +
    '<h3 class="install-modal-title"><i class="fa-regular fa-clock"></i> Temps passé</h3>' +
    '<p class="install-modal-text">Pour rester en bonne santé numérique, il est conseillé de ne pas rester plus de 60 minutes par jour sur les réseaux et plateformes comme agôn. Ce compteur ne bloque rien, c\'est juste un repère.</p>' +
    '<button class="install-modal-android-btn" type="button" style="display:flex">Compris</button>' +
    '</div>';
  const close = () => overlay.remove();
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
  overlay.querySelector(".install-modal-android-btn").addEventListener("click", close);
  document.body.appendChild(overlay);
}

function isAgonMobileCloudViewport() {
  const viewportWidth = Math.min(
    window.innerWidth || Number.POSITIVE_INFINITY,
    window.visualViewport?.width || Number.POSITIVE_INFINITY
  );
  const cssMobile = viewportWidth <= 768 || window.matchMedia("(max-width: 768px)").matches;
  const coarseTouch = window.matchMedia("(hover: none) and (pointer: coarse)").matches
    || Number(navigator.maxTouchPoints || 0) > 1;
  const narrowDevice = Math.min(screen.width || 9999, screen.height || 9999) <= 820;

  return cssMobile || (isStandaloneMode() && coarseTouch && narrowDevice);
}

function syncAgonMobileCloudViewportClass() {
  if (!document.body) return;
  document.body.classList.toggle("agon-mobile-cloud-viewport", isAgonMobileCloudViewport());
}

syncAgonMobileCloudViewportClass();
window.addEventListener("resize", syncAgonMobileCloudViewportClass, { passive: true });
window.visualViewport?.addEventListener("resize", syncAgonMobileCloudViewportClass, { passive: true });

function ensurePushMenuItemElement() {
  let item = document.getElementById("push-menu-item");
  if (item) return item;

  const menu = document.getElementById("home-topbar-menu");
  if (!menu) return null;

  item = document.createElement("button");
  item.type = "button";
  item.className = "home-topbar-menu-item";
  item.id = "push-menu-item";
  item.style.display = "none";
  item.setAttribute("onclick", "handlePushMenuClick()");
  item.innerHTML = '<i id="push-menu-icon" class="fa-regular fa-bell"></i><span id="push-menu-label">Activer les alertes</span>';

  const notificationsLink = document.getElementById("home-topbar-notifications-link")
    || Array.from(menu.querySelectorAll(".home-topbar-menu-item")).find((link) => {
      const text = (link.textContent || "").trim().toLowerCase();
      return text.includes("notification");
    });
  if (notificationsLink && notificationsLink.parentNode === menu) {
    notificationsLink.insertAdjacentElement("afterend", item);
  } else {
    menu.appendChild(item);
  }

  return item;
}

