function showPushInvite(reason = "action", options = {}) {
  if (pushInviteToastEl || !shouldShowPushInvite(options)) return;

  ensurePushInviteStyles();
  lsSet(PUSH_INVITE_LAST_SHOWN_KEY, String(Date.now()));

  const toast = document.createElement("div");
  toast.className = "push-invite-toast";
  toast.setAttribute("role", "dialog");
  toast.dataset.reason = reason;

  const copy = document.createElement("div");
  copy.className = "push-invite-copy";

  const title = document.createElement("p");
  title.className = "push-invite-title";

  const text = document.createElement("p");
  text.className = "push-invite-text";

  const actions = document.createElement("div");
  actions.className = "push-invite-actions";

  const laterButton = document.createElement("button");
  laterButton.type = "button";
  laterButton.className = "push-invite-btn push-invite-btn-secondary";
  laterButton.textContent = "Plus tard";
  laterButton.addEventListener("click", hidePushInvite);

  const primaryButton = document.createElement("button");
  primaryButton.type = "button";
  primaryButton.className = "push-invite-btn push-invite-btn-primary";

  if (isStandaloneMode()) {
    // app installée → invite push notifs
    toast.setAttribute("aria-label", "Notifications");
    title.textContent = "On te prévient quand ça réagit à tes publications ?";
    text.textContent = "Juste les réponses à tes posts — rien d'autre, jamais.";
    primaryButton.textContent = "Activer";
    // Ferme la modale immédiatement au clic : la chaîne async qui suit (permission
    // navigateur, service worker, sauvegarde serveur) prenait jusque-là un temps de
    // latence visible avant que la modale ne disparaisse.
    primaryButton.addEventListener("click", () => {
      hidePushInvite();
      enablePushNotificationsFromInvite();
    });
  } else if (isIOSDevice()) {
    // iPhone / iPad → guide install PWA
    toast.setAttribute("aria-label", "Installer Agôn");
    title.textContent = "Ajoute Agôn à ton écran";
    text.textContent = "Sans compte. Zéro mémoire — juste une icône Safari.";
    primaryButton.textContent = "Voir comment";
    primaryButton.addEventListener("click", () => {
      hidePushInvite();
      if (typeof window.openInstallModal === "function") {
        window.openInstallModal();
      } else {
        openInstallModalFallback();
      }
    });
  } else {
    // Android → install PWA
    toast.setAttribute("aria-label", "Installer Agôn");
    title.textContent = "Installe Agôn";
    text.textContent = "Sans compte. Zéro mémoire prise sur le téléphone. Une icône, c'est tout.";
    primaryButton.textContent = "Installer";
    primaryButton.addEventListener("click", () => {
      hidePushInvite();
      if (typeof window.triggerAndroidInstall === "function") window.triggerAndroidInstall();
      else if (typeof window.openInstallModal === "function") window.openInstallModal();
    });
  }

  const icon = document.createElement("div");
  icon.className = "push-invite-icon";
  icon.innerHTML = '<img src="/icon-192-optimized.png" alt="Agôn">';

  copy.append(title, text);
  actions.append(primaryButton, laterButton);

  toast.append(icon, copy, actions);

  const overlay = document.createElement("div");
  overlay.className = "push-invite-overlay";
  overlay.setAttribute("role", "dialog");
  overlay.addEventListener("click", (e) => { if (e.target === overlay) hidePushInvite(); });
  overlay.appendChild(toast);

  document.body.appendChild(overlay);
  pushInviteToastEl = overlay;
}

function showPushInviteAfterAction(reason = "action") {
  window.setTimeout(() => {
    try {
      if (window !== window.top) {
        window.parent.postMessage({ type: "agon:push-invite-action", reason }, "*");
        return;
      }
      showPushInvite(reason, { ignoreCooldown: true });
    } catch {}
  }, 450);
}

window.addEventListener("message", (e) => {
  if (e.data?.type === "agon:push-invite-action" && window === window.top) {
    try { showPushInvite(e.data.reason || "action", { ignoreCooldown: true }); } catch {}
  }
});

