function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function escapeHtmlNl(str) {
  return escapeHtml(str).replace(/\n/g, "<br>");
}

function escapeAttribute(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("'", "&#039;");
}

function getDomainLabel(url) {
  try {
    return new URL(String(url || "")).hostname.replace(/^www\./, "");
  } catch (error) {
    return "Source externe";
  }
}

function truncateSourcePreviewText(text, maxLength = 240) {
  const normalized = String(text || "").replace(/\s+/g, " ").trim();
  if (!normalized) return "";
  if (normalized.length <= maxLength) return normalized;
  return `${normalized.slice(0, Math.max(0, maxLength - 1)).trim()}…`;
}

function pickFirstSourcePreviewValue(...values) {
  for (const value of values) {
    if (typeof value === "string") {
      const normalized = value.trim();
      if (normalized) return normalized;
      continue;
    }

    if (Array.isArray(value)) {
      const picked = pickFirstSourcePreviewValue(...value);
      if (picked) return picked;
      continue;
    }

    if (value && typeof value === "object") {
      const picked = pickFirstSourcePreviewValue(
        value.url,
        value.secure_url,
        value.src,
        value.href,
        value.content,
        value.image,
        value.thumbnail
      );
      if (picked) return picked;
    }
  }

  return "";
}

function normalizeSourcePreviewData(preview, sourceUrl = "") {
  const safePreview = preview && typeof preview === "object" ? preview : {};
  const safeUrl = pickFirstSourcePreviewValue(
    safePreview.finalUrl,
    safePreview.canonicalUrl,
    safePreview.url,
    sourceUrl
  );
  const domain = pickFirstSourcePreviewValue(
    safePreview.siteName,
    safePreview.domain,
    safePreview.publisher,
    safePreview.provider,
    safePreview.source,
    getDomainLabel(safeUrl || sourceUrl)
  ) || "Source externe";
  const title = pickFirstSourcePreviewValue(
    safePreview.title,
    safePreview.ogTitle,
    safePreview.metaTitle,
    safePreview.headline,
    safePreview.name,
    domain,
    "Source externe"
  ) || "Source externe";
  const description = truncateSourcePreviewText(
    pickFirstSourcePreviewValue(
      safePreview.description,
      safePreview.ogDescription,
      safePreview.metaDescription,
      safePreview.excerpt,
      safePreview.summary,
      safePreview.text,
      safePreview.content,
      safePreview.snippet
    ),
    240
  );
  const image = pickFirstSourcePreviewValue(
    safePreview.image,
    safePreview.imageUrl,
    safePreview.thumbnail,
    safePreview.thumbnailUrl,
    safePreview.ogImage,
    safePreview.cover,
    safePreview.poster,
    safePreview.posterUrl,
    safePreview.media?.image,
    safePreview.images
  );

  return {
    url: safeUrl,
    domain,
    title,
    description,
    image,
    videoDurationSeconds: getAgonVideoDurationSeconds(safePreview)
  };
}

function getAgonVideoDurationSeconds(value) {
  const rawValue = value && typeof value === "object"
    ? (value.videoDurationSeconds ?? value.durationSeconds ?? value.video_duration_seconds ?? value.duration_seconds)
    : value;
  const seconds = Number(rawValue);
  return Number.isFinite(seconds) && seconds > 0 ? Math.round(seconds) : 0;
}

function formatAgonVideoDuration(value) {
  const totalSeconds = getAgonVideoDurationSeconds(value);
  if (!totalSeconds) return "";

  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) {
    return `${hours}:${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
  }
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

function buildAgonVideoDurationBadgeHtml(value) {
  const label = formatAgonVideoDuration(value);
  return `<span class="agon-video-duration-badge" data-video-duration-badge${label ? "" : " hidden"}>${escapeHtml(label)}</span>`;
}

function updateAgonVideoDurationBadge(shell, value) {
  const badge = shell?.querySelector?.("[data-video-duration-badge]");
  if (!badge) return;

  const seconds = getAgonVideoDurationSeconds(value);
  const label = formatAgonVideoDuration(seconds);
  if (seconds) shell.dataset.videoDurationSeconds = String(seconds);
  badge.textContent = label;
  badge.hidden = !label || shell.dataset.active === "true";
}

const pendingAgonYouTubeDurationHydrations = new Map();
let agonYouTubeDurationObserver = null;

async function hydrateAgonYouTubeDuration(shell) {
  if (!shell || getAgonVideoDurationSeconds(shell.dataset.videoDurationSeconds) > 0) return;

  const sourceUrl = String(shell.dataset.sourceUrl || "").trim();
  if (!sourceUrl) return;

  let pending = pendingAgonYouTubeDurationHydrations.get(sourceUrl);
  if (!pending) {
    pending = getIndexSourcePreviewData(sourceUrl, { forceRefresh: true })
      .finally(() => pendingAgonYouTubeDurationHydrations.delete(sourceUrl));
    pendingAgonYouTubeDurationHydrations.set(sourceUrl, pending);
  }

  try {
    const preview = await pending;
    const durationSeconds = getAgonVideoDurationSeconds(preview);
    if (!durationSeconds) return;

    document.querySelectorAll("[data-index-youtube-shell]").forEach((candidate) => {
      if (String(candidate.dataset.sourceUrl || "").trim() === sourceUrl) {
        updateAgonVideoDurationBadge(candidate, durationSeconds);
      }
    });
  } catch (error) {
    // Une durée indisponible ne doit jamais empêcher l'affichage de la vidéo.
  }
}

function observeAgonYouTubeDurations(root = document) {
  const scope = root && typeof root.querySelectorAll === "function" ? root : document;
  const shells = Array.from(scope.querySelectorAll("[data-index-youtube-shell]"));
  if (!shells.length) return;

  if (!agonYouTubeDurationObserver && typeof IntersectionObserver === "function") {
    agonYouTubeDurationObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        agonYouTubeDurationObserver.unobserve(entry.target);
        hydrateAgonYouTubeDuration(entry.target);
      });
    }, {
      root: null,
      rootMargin: "600px 0px",
      threshold: 0.01
    });
  }

  shells.forEach((shell) => {
    if (getAgonVideoDurationSeconds(shell.dataset.videoDurationSeconds) > 0) return;
    if (agonYouTubeDurationObserver) {
      agonYouTubeDurationObserver.observe(shell);
    } else {
      hydrateAgonYouTubeDuration(shell);
    }
  });
}

function isWeakSourcePreviewData(preview, sourceUrl = "") {
  const normalized = normalizeSourcePreviewData(preview, sourceUrl);
  const title = String(normalized.title || "").trim().toLowerCase();
  const description = String(normalized.description || "").trim().toLowerCase();
  const image = String(normalized.image || "").trim();

  if (!title || title === "source externe") return true;
  if (!image && (!description || description === "source externe")) return true;

  const blockedMarkers = [
    "access denied",
    "just a moment",
    "attention required",
    "enable javascript",
    "verify you are human"
  ];

  return blockedMarkers.some((marker) => title.includes(marker) || description.includes(marker));
}

function buildXIndexSourceCardHtml(sourceUrl, preview = null, debateId = "") {
  const normalizedPreview = normalizeSourcePreviewData(preview, sourceUrl);
  const title = normalizedPreview.title && normalizedPreview.title !== "Source externe"
    ? normalizedPreview.title
    : "Source publiée sur X";
  const description = normalizedPreview.description || "Voir le post source sur X.";
  const image = normalizedPreview.image || "";
  const safeDebateId = escapeAttribute(String(debateId || "").trim());
  const rootClickAttr = safeDebateId
    ? `onclick="openIndexDebateFromMedia('${safeDebateId}', event)" style="display:block; overflow:hidden; border-radius:0; background:#ffffff; color:inherit; cursor:pointer;"`
    : `style="display:block; overflow:hidden; border-radius:0; background:#ffffff; color:inherit;"`;

  return `
    <div
      class="debate-card-source debate-card-source-x"
      ${rootClickAttr}
    >
      ${image ? `
        <div style="display:block; width:100%; aspect-ratio:16/9; background:#f3f4f6; overflow:hidden;">
          <img
            src="${escapeAttribute(image)}"
            alt="Aperçu du post X"
            loading="lazy"
            decoding="async"
            style="display:block; width:100%; height:100%; object-fit:cover;"
            onerror="this.onerror=null; this.src='/fondchargement-256.png';"
          >
        </div>
      ` : ""}
      <div style="padding:10px 16px 14px; display:flex; flex-direction:column; gap:6px;">
        <div style="font-size:12px; line-height:1.4; font-weight:700; color:#6b7280; text-transform:uppercase; letter-spacing:0.04em;">𝕏 Source</div>
        <div style="font-size:18px; line-height:1.35; font-weight:800; color:#111827;">${escapeHtml(title)}</div>
        <div style="font-size:14px; line-height:1.55; color:#4b5563;">${escapeHtml(description)}</div>
      </div>
    </div>
  `;
}


function buildIndexCardMetaHtml(debate, options = {}) {
  const d = debate || {};
  const mediaOutsideLink = !!options.mediaOutsideLink;
  const voteCount = d.vote_count || (Number(d.votes_a || 0) + Number(d.votes_b || 0));
  const ideaCount = d.argument_count || 0;
  const commentCount = d.comment_count || 0;
  const statParts = [];
  if (ideaCount >= 1) statParts.push(`${ideaCount} idée${ideaCount >= 2 ? 's' : ''}`);
  if (commentCount >= 1) statParts.push(`${commentCount} commentaire${commentCount > 1 ? 's' : ''}`);
  if (voteCount > 0) statParts.push(`${voteCount} voix`);
  const countsHtml = statParts.length > 0 ? `
    <div class="debate-card-counts-row">
      <p class="debate-card-stats-badge">${statParts.join(' · ')}</p>
    </div>
  ` : '';
  return `
    <div class="debate-card-meta-below-media ${mediaOutsideLink ? '' : 'debate-card-meta-no-media'}">
      ${countsHtml}
      <p class="debate-date">${escapeHtml(formatDebateDate(d.created_at))}</p>
      ${getDebateLastActivityAt(d) ? `<p class="debate-last-argument">${escapeHtml(formatLastActivityDate(getDebateLastActivityAt(d)))}</p>` : ""}
    </div>
  `;
}

function buildIndexCardBottomEntryHtml(debate, options = {}) {
  return "";
}

function getDebateSourceCount(debate) {
  const d = debate || {};
  const mainSourceUrl = String(d.source_url || '').trim();
  const extras = Array.isArray(d.media_extras) ? d.media_extras : [];
  const sourceExtras = extras.filter(e => e && String(e.type || '').trim() === 'source' && String(e.url || '').trim());
  const allUrls = new Set();
  if (mainSourceUrl) allUrls.add(mainSourceUrl);
  sourceExtras.forEach(e => { const u = String(e.url || '').trim(); if (u) allUrls.add(u); });
  return allUrls.size;
}

function getDebatePrimaryMediaName(debate) {
  const d = debate || {};
  const sourceUrl = String(d.source_url || '').trim();
  if (!sourceUrl && !d.source_preview) return '';
  const normalized = normalizeSourcePreviewData(d.source_preview || null, sourceUrl);
  return String(normalized.domain || '').trim();
}

function buildIndexCardSourceLabelHtml(debate) {
  const sourceCount = getDebateSourceCount(debate);
  if (!sourceCount) return '';
  const mediaName = getDebatePrimaryMediaName(debate) || 'Source inconnue';
  const label = sourceCount > 1
    ? `${mediaName} + ${sourceCount} source${sourceCount >= 2 ? 's' : ''}`
    : mediaName;
  return `<span class="debate-card-source-label">${escapeHtml(label)}</span>`;
}

function getDebateSourceLabelText(debate) {
  const sourceCount = getDebateSourceCount(debate);
  if (!sourceCount) return '';
  const mediaName = getDebatePrimaryMediaName(debate) || 'Source inconnue';
  return sourceCount > 1
    ? `${mediaName} + ${sourceCount} source${sourceCount >= 2 ? 's' : ''}`
    : mediaName;
}

