const INDEX_OG_IMAGE_LOADED_CACHE_MAX = 120;
const indexOpenGraphLoadedImageUrls = new Set();

// Logo Libération : utilisé uniquement en secours quand l'image d'un article
// liberation.fr échoue au chargement (jamais en premier choix).
const LIBERATION_FALLBACK_IMAGE = 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Lib%C3%A9ration.svg/langfr-250px-Lib%C3%A9ration.svg.png';

function isLiberationSourceUrl(url) {
  return /liberation\.fr/i.test(String(url || ''));
}

// Logo Le Point : lepoint.fr est protégé par un anti-bot (DataDome) qui bloque
// systématiquement la récupération d'og:image (403 sur tous les profils UA,
// y compris Googlebot/Facebook/Twitter) — jamais d'image d'origine possible.
const LEPOINT_FALLBACK_IMAGE = 'https://upload.wikimedia.org/wikipedia/en/thumb/1/15/Le_Point_Logo.svg/250px-Le_Point_Logo.svg.png';

function isLePointSourceUrl(url) {
  return /lepoint\.fr/i.test(String(url || ''));
}

function normalizeIndexOpenGraphImageCacheUrl(url) {
  return String(url || '').trim();
}

function hasLoadedIndexOpenGraphImage(url) {
  const key = normalizeIndexOpenGraphImageCacheUrl(url);
  return !!key && indexOpenGraphLoadedImageUrls.has(key);
}

function markIndexOpenGraphImageLoaded(url) {
  const key = normalizeIndexOpenGraphImageCacheUrl(url);
  if (!key) return;
  if (indexOpenGraphLoadedImageUrls.has(key)) {
    indexOpenGraphLoadedImageUrls.delete(key);
  }
  indexOpenGraphLoadedImageUrls.add(key);
  while (indexOpenGraphLoadedImageUrls.size > INDEX_OG_IMAGE_LOADED_CACHE_MAX) {
    const oldestKey = indexOpenGraphLoadedImageUrls.keys().next().value;
    indexOpenGraphLoadedImageUrls.delete(oldestKey);
  }
}

function renderIndexOpenGraphImageShell(shell) {
  if (!shell || shell.dataset.rendered === 'true' || shell.dataset.rendering === 'true') return;

  const imageUrl = String(shell.dataset.imageSrc || '').trim();
  const img = shell.querySelector('[data-index-og-image]');
  const loading = shell.querySelector('[data-index-og-image-loading]');
  if (!imageUrl || !img) return;

  shell.dataset.rendering = 'true';
  if (loading) loading.style.display = '';

  // Important : ne pas laisser l'image en display:none pendant le chargement.
  // Sur certains navigateurs, une image lazy + display:none peut ne jamais déclencher onload,
  // ce qui laisse le placeholder Open Graph affiché indéfiniment.
  img.style.display = 'block';
  img.style.opacity = '0';

  const clearTimer = () => {
    if (shell.dataset.ogImageFallbackTimer) {
      clearTimeout(Number(shell.dataset.ogImageFallbackTimer));
      delete shell.dataset.ogImageFallbackTimer;
    }
  };

  const finish = () => {
    clearTimer();
    markIndexOpenGraphImageLoaded(imageUrl);
    img.style.display = 'block';
    img.style.opacity = '1';
    if (loading) loading.style.display = 'none';
    shell.dataset.rendered = 'true';
    shell.dataset.rendering = 'false';
  };

  const fail = () => {
    clearTimer();
    shell.dataset.rendered = 'fallback';
    shell.dataset.rendering = 'false';
    img.style.display = 'block';
    img.style.opacity = '0';
    if (loading) loading.style.display = '';

    // Secours spécifique Libération : uniquement quand l'image d'origine échoue,
    // jamais affiché en premier choix.
    const canTryLiberationFallback = isLiberationSourceUrl(shell.dataset.sourceUrl)
      && shell.dataset.triedLiberationFallback !== 'true'
      && img.getAttribute('src') !== LIBERATION_FALLBACK_IMAGE;
    if (canTryLiberationFallback) {
      shell.dataset.triedLiberationFallback = 'true';
      img.onload = finish;
      img.onerror = fail;
      shell.style.background = '#ffffff';
      img.classList.add('debate-source-card-image-logo');
      img.src = LIBERATION_FALLBACK_IMAGE;
      return;
    }

    // Secours spécifique Le Point : même mécanique que Libération.
    const canTryLePointFallback = isLePointSourceUrl(shell.dataset.sourceUrl)
      && shell.dataset.triedLePointFallback !== 'true'
      && img.getAttribute('src') !== LEPOINT_FALLBACK_IMAGE;
    if (canTryLePointFallback) {
      shell.dataset.triedLePointFallback = 'true';
      img.onload = finish;
      img.onerror = fail;
      shell.style.background = '#ffffff';
      img.classList.add('debate-source-card-image-logo');
      img.src = LEPOINT_FALLBACK_IMAGE;
      return;
    }

    img.onerror = null;
    img.onload = finish;
    if (img.getAttribute('src') !== '/fondchargement-256.png') {
      img.src = '/fondchargement-256.png';
    } else {
      finish();
    }
  };

  img.onload = finish;
  img.onerror = fail;

  if (img.getAttribute('src') !== imageUrl) {
    img.src = imageUrl;
  } else if (img.complete && img.naturalWidth > 0) {
    finish();
    return;
  }

  // Filet de sécurité : si le navigateur a bien téléchargé l'image mais n'a pas lancé
  // l'événement attendu, on libère quand même le placeholder. Sinon on garde un fallback visuel.
  const fallbackTimer = window.setTimeout(() => {
    if (img.complete && img.naturalWidth > 0) {
      finish();
    } else {
      fail();
    }
  }, 10000);

  shell.dataset.ogImageFallbackTimer = String(fallbackTimer);
}

function removeFailedIndexSourceFromSwipe(imageShell) {
  const swipeShell = imageShell?.closest?.('[data-index-media-swipe-shell]');
  if (!swipeShell) return false;

  let mediaItems;
  try {
    mediaItems = JSON.parse(swipeShell.dataset.mediaItems || '[]');
  } catch {
    return false;
  }
  if (!Array.isArray(mediaItems) || !mediaItems.length) return false;

  const currentIndex = Number(swipeShell.dataset.currentIndex || '0') || 0;
  const currentItem = mediaItems[currentIndex] || null;
  const failedSourceUrl = String(swipeShell.dataset.currentSourceUrl || currentItem?.url || '').trim();
  if (!failedSourceUrl) return false;

  const nextItems = mediaItems.filter((item) => {
    return !(String(item?.type || '').trim() === 'source' && String(item?.url || '').trim() === failedSourceUrl);
  });

  if (nextItems.length === mediaItems.length) return false;

  const debateId = String(swipeShell.dataset.debateId || '').trim();
  const debate = getIndexDebateById(debateId) || { id: debateId };

  if (!nextItems.length) {
    swipeShell.remove();
    return true;
  }

  const nextIndex = Math.min(currentIndex, nextItems.length - 1);
  const nextItem = nextItems[nextIndex];
  const nextPreview = String(nextItem?.type || '').trim() === 'source'
    ? getResolvedIndexSourcePreview(String(nextItem.url || '').trim(), debate)
    : null;
  const nextHtml = renderIndexMediaItemHtml(nextItem, debate, nextPreview, {
    showSourceBadgeWithoutImage: swipeShell.dataset.showSourceBadgeWithoutImage === '1'
  });
  if (!nextHtml) {
    swipeShell.remove();
    return true;
  }

  if (nextItems.length === 1) {
    swipeShell.insertAdjacentHTML('afterend', nextHtml);
    const replacement = swipeShell.nextElementSibling;
    swipeShell.remove();
    if (replacement) refreshIndexCardMediaEnhancements(replacement.closest('.debate-card') || replacement);
    return true;
  }

  const inner = swipeShell.querySelector('[data-index-media-swipe-content]');
  if (!inner) return false;
  inner.innerHTML = nextHtml;
  swipeShell.dataset.mediaItems = JSON.stringify(nextItems);
  swipeShell.dataset.currentIndex = String(nextIndex);
  swipeShell.dataset.currentSourceUrl = String(nextItem?.type || '').trim() === 'source'
    ? String(nextItem.url || '').trim()
    : '';
  swipeShell.dataset.currentSourcePreview = JSON.stringify(nextPreview || null);
  refreshIndexCardMediaEnhancements(swipeShell.closest('.debate-card') || swipeShell);
  return true;
}

function unloadIndexOpenGraphImageShell(shell) {
  if (!shell) return;
  const img = shell.querySelector('[data-index-og-image]');
  const loading = shell.querySelector('[data-index-og-image-loading]');

  if (img) {
    img.onload = null;
    img.onerror = null;
    img.removeAttribute('src');
    img.style.display = 'none';
    img.style.opacity = '0';
  }

  if (shell.dataset.ogImageFallbackTimer) {
    clearTimeout(Number(shell.dataset.ogImageFallbackTimer));
    delete shell.dataset.ogImageFallbackTimer;
  }

  delete shell.dataset.triedLiberationFallback;
  delete shell.dataset.triedLePointFallback;
  if (loading) loading.style.display = '';
  shell.dataset.rendered = 'false';
  shell.dataset.rendering = 'false';
  window.indexOpenGraphImageState?.observer?.observe(shell);
}

function initIndexOpenGraphImageObserver(root = document) {
  const scope = root && typeof root.querySelectorAll === 'function' ? root : document;
  const shells = Array.from(scope.querySelectorAll('[data-index-og-image-shell]'));
  const previousState = window.indexOpenGraphImageState;

  if (!shells.length && !previousState) return;

  if (typeof IntersectionObserver !== 'function') {
    shells.forEach((shell) => renderIndexOpenGraphImageShell(shell));
    return;
  }

  if (!previousState?.observer) {
    window.indexOpenGraphImageState = {
      observer: new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          const shell = entry.target;
          if (!entry.isIntersecting || entry.intersectionRatio < 0.08) return;
          renderIndexOpenGraphImageShell(shell);
        });
      }, {
        root: null,
        rootMargin: '500px 0px 500px 0px',
        threshold: [0, 0.08, 0.35]
      }),
      shells: new Set()
    };
  }

  const state = window.indexOpenGraphImageState;
  shells.forEach((shell) => {
    if (state.shells.has(shell)) return;
    state.shells.add(shell);
    if (!shell.dataset.rendered) shell.dataset.rendered = 'false';
    state.observer.observe(shell);
    if (isElementNearViewport(shell, 220)) {
      requestAnimationFrame(() => renderIndexOpenGraphImageShell(shell));
    }
  });
}

function buildIndexEmbedLoadingContent(preview, type) {
  const img = normalizeSourcePreviewData(preview, '').image;
  if (img) {
    return `<img src="${escapeHtml(img)}" alt="" style="width:100%;height:100%;object-fit:cover;display:block;border-radius:inherit;" loading="lazy">`;
  }
  const titles = { x: 'Chargement du post X…', instagram: 'Chargement du post Instagram…' };
  const subs = { x: 'Le post arrive dès que X termine de répondre.', instagram: 'Le post se prépare avant affichage dans la carte.' };
  return buildIndexSocialLoadingPlaceholderHtml(type, titles[type] || 'Chargement…', subs[type] || '');
}

