/* =========================
   Admin
========================= */

let adminSessionVerified = false;
let adminSessionVerificationPromise = null;

function getAdminToken() {
  return localStorage.getItem("admin_token");
}

function isAdmin() {
  return !!getAdminToken() && adminSessionVerified;
}

// Pour les arènes officielles (créées par l'admin), permet au compte admin de
// rester reconnu comme "propriétaire" côté serveur (ex: accès au barème caché)
// même si la clé de navigateur ne correspond pas à creator_key. On envoie le
// token dès qu'il existe en local, sans attendre la vérification asynchrone
// (adminSessionVerified) : le serveur est seul juge de sa validité, et
// attendre cette vérification créait une race au chargement de la page
// débat (token envoyé trop tard, barème caché vu comme non-propriétaire).
function debateOwnerHeaders() {
  const token = getAdminToken();
  return token ? { "x-admin-token": token } : {};
}

function setAdminToken(token) {
  localStorage.setItem("admin_token", token);
  adminSessionVerified = !!token;
}

function clearAdminToken() {
  localStorage.removeItem("admin_token");
  adminSessionVerified = false;
}

function refreshAdminUI() {
  const adminMode = isAdmin();
  const root = document.documentElement;
  const loginBtn = document.getElementById("admin-login-btn");
  const mobileLoginBtn = document.getElementById("home-topbar-admin-login-button");
  const logoutBtn = document.getElementById("admin-logout-btn");
  const badge = document.getElementById("admin-badge");

  if (root) {
    root.classList.add("admin-ui-ready");
    root.classList.toggle("admin-mode", adminMode);
  }

  if (loginBtn) {
    loginBtn.style.display = adminMode ? "none" : "inline-block";
  }

  if (mobileLoginBtn) {
    mobileLoginBtn.style.display = adminMode ? "none" : "";
  }

  if (logoutBtn) {
    logoutBtn.style.display = adminMode ? "inline-block" : "none";
  }

  if (badge) {
    badge.style.display = adminMode ? "inline-flex" : "none";
  }

  document.querySelectorAll("[data-admin]").forEach(el => {
    el.style.display = adminMode ? "" : "none";
  });

  if (adminMode) {
    initAdminEditCategoryPickers(document);
  }
}

async function verifyAdminSession(force = false) {
  const token = getAdminToken();

  if (!token) {
    clearAdminToken();
    refreshAdminUI();
    return false;
  }

  if (!force && adminSessionVerified) {
    refreshAdminUI();
    return true;
  }

  if (!force && adminSessionVerificationPromise) {
    return adminSessionVerificationPromise;
  }

  adminSessionVerificationPromise = (async () => {
    try {
      await fetchJSON(API + "/admin/session", {
        headers: {
          "x-admin-token": token
        }
      });

      adminSessionVerified = true;
      refreshAdminUI();
      return true;
    } catch (error) {
      clearAdminToken();
      refreshAdminUI();
      return false;
    } finally {
      adminSessionVerificationPromise = null;
    }
  })();

  return adminSessionVerificationPromise;
}

function showAdminLoginModal() {
  return new Promise((resolve) => {
    const existing = document.getElementById("custom-admin-login-modal");
    if (existing) existing.remove();

    const overlay = document.createElement("div");
    overlay.id = "custom-admin-login-modal";
    overlay.className = "custom-modal-overlay";
    overlay.innerHTML = `
      <div class="custom-modal-box" style="max-width:420px; width:min(92vw,420px);">
        <div class="custom-modal-title">Mode admin</div>
        <div class="custom-modal-text">Entrez le mot de passe administrateur.</div>
        <input
          id="custom-admin-login-password"
          type="password"
          autocomplete="current-password"
          placeholder="Mot de passe"
          class="admin-edit-input"
          style="margin-top:12px;"
        >
        <div class="custom-modal-actions" style="margin-top:16px;">
          <button type="button" class="button button-secondary" id="custom-admin-login-cancel">Annuler</button>
          <button type="button" class="button" id="custom-admin-login-confirm">Entrer</button>
        </div>
      </div>
    `;

    const close = (value = "") => {
      overlay.remove();
      resolve(String(value || ""));
    };

    document.body.appendChild(overlay);

    const passwordInput = document.getElementById("custom-admin-login-password");
    const cancelBtn = document.getElementById("custom-admin-login-cancel");
    const confirmBtn = document.getElementById("custom-admin-login-confirm");

    const submit = () => close(passwordInput?.value || "");

    cancelBtn?.addEventListener("click", () => close(""));
    confirmBtn?.addEventListener("click", submit);
    overlay.addEventListener("click", (event) => {
      if (event.target === overlay) close("");
    });
    passwordInput?.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        submit();
      }
      if (event.key === "Escape") {
        event.preventDefault();
        close("");
      }
    });

    setTimeout(() => passwordInput?.focus(), 0);
  });
}

async function adminLogin() {
  const password = await showAdminLoginModal();
  if (!password) return;

  try {
    const result = await fetchJSON(API + "/admin/login", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ password })
    });

    setAdminToken(result.token);
    refreshAdminUI();
  } catch (error) {
    alert(error.message);
  }
}

async function adminLogout() {
  const token = getAdminToken();
  if (!token) return;

  try {
    const result = await fetchJSON(API + "/admin/logout", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-admin-token": token
      }
    });

    if (result.error) {
      alert(result.error);
      return;
    }

    clearAdminToken();
    refreshAdminUI();
    __agonRecordReloadReason("admin-logout");
    try { sessionStorage.setItem('agon_skip_startup_once', '1'); } catch (e) {}
    location.reload();
  } catch (error) {
    alert(error.message);
  }
}

function attachAdminButtons() {
  const loginBtn = document.getElementById("admin-login-btn");
  const logoutBtn = document.getElementById("admin-logout-btn");

  if (loginBtn) {
    loginBtn.addEventListener("click", adminLogin);
  }

  if (logoutBtn) {
    logoutBtn.addEventListener("click", adminLogout);
  }

  const updateCloudBtn = document.getElementById("admin-update-cloud-btn");
  if (updateCloudBtn) {
    updateCloudBtn.addEventListener("click", async () => {
      updateCloudBtn.disabled = true;
      updateCloudBtn.textContent = "⟳ Mise à jour…";
      try {
        const res = await fetchJSON(API + "/admin/update-cloud", {
          method: "POST",
          headers: { "Content-Type": "application/json", "x-admin-token": getAdminToken() },
          body: JSON.stringify({})
        });
        updateCloudBtn.textContent = "✓ " + (res.count || 0) + " bulle(s) mises à jour";
        setTimeout(() => { updateCloudBtn.textContent = "⟳ Mettre à jour les bulles"; updateCloudBtn.disabled = false; }, 3000);
        try {
          const cloudRes = await fetchJSON(API + "/cloud-bubbles");
          const newTrends = Array.isArray(cloudRes?.bubbles) ? cloudRes.bubbles : [];
          window.AGON_TAG_TRENDS = newTrends;
          syncIndexBubbleTrendBadges();
          if (window._tagTrendCloudModule && newTrends.length) {
            const container = document.querySelector("#agon-tag-trends-cloud");
            if (container) window._tagTrendCloudModule.renderTagTrendCloud(container, newTrends);
          }
        } catch {}
      } catch (e) {
        updateCloudBtn.textContent = "⚠ Erreur";
        setTimeout(() => { updateCloudBtn.textContent = "⟳ Mettre à jour les bulles"; updateCloudBtn.disabled = false; }, 3000);
      }
    });
  }

  const broadcastDailyBtn = document.getElementById("admin-broadcast-daily-btn");
  if (broadcastDailyBtn) {
    broadcastDailyBtn.addEventListener("click", adminBroadcastDaily);
  }

  initAdminTopbarMenu();
  refreshAdminUI();
  verifyAdminSession();
}

async function adminBroadcastDaily() {
  const btn = document.getElementById("admin-broadcast-daily-btn");
  if (btn) { btn.disabled = true; }
  try {
    const res = await fetchJSON(API + "/admin/push/broadcast-daily", { method: "POST", headers: { "x-admin-token": getAdminToken() } });
    const sent = (res.results || []).filter(r => r.status === "sent").length;
    showReplacementSuccessMessage(
      "Push envoyé",
      `« ${res.body || ""} » envoyé à ${sent} / ${res.total} abonné(s).`,
      null,
      "🔔"
    );
  } catch (e) {
    alert("Erreur lors de l'envoi du push.");
  } finally {
    if (btn) { btn.disabled = false; }
  }
}

function initAdminTopbarMenu() {
  const menu = document.getElementById("admin-topbar-menu");
  const toggle = document.getElementById("admin-topbar-menu-toggle");
  const panel = document.getElementById("admin-topbar-menu-panel");
  if (!menu || !toggle || !panel || menu.dataset.bound === "1") return;

  menu.dataset.bound = "1";

  const close = () => {
    panel.hidden = true;
    toggle.setAttribute("aria-expanded", "false");
    document.body.classList.remove("admin-menu-is-open");
  };

  const open = () => {
    panel.hidden = false;
    toggle.setAttribute("aria-expanded", "true");
    document.body.classList.add("admin-menu-is-open");
    const rect = toggle.getBoundingClientRect();
    panel.style.top = (rect.bottom + 8) + 'px';
    panel.style.right = '';
    panel.style.left = '50%';
    panel.style.transform = 'translateX(-50%)';
  };

  toggle.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    panel.hidden ? open() : close();
  });

  document.addEventListener("click", (event) => {
    if (!event.isTrusted) return;
    if (!menu.contains(event.target)) close();
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") close();
  });

  panel.querySelectorAll("a, button").forEach((item) => {
    if (item.id === "admin-logout-btn") return;
    item.addEventListener("click", close);
  });
}
