function ensureOwnerDeleteButtonStyles() {
  if (document.getElementById("owner-delete-button-style")) return;

  const style = document.createElement("style");
  style.id = "owner-delete-button-style";
  style.textContent = `
    .debate-card {
      position: relative;
    }

    .debate-card-delete-button,
    #delete-debate-btn {
      display: flex !important;
      align-items: center;
      justify-content: center;
      width: 32px;
      height: 32px;
      min-width: 32px;
      padding: 0;
      border-radius: 999px;
      font-size: 24px;
      line-height: 1;
      font-weight: 700;
      z-index: 50;
      cursor: pointer;
    }

    .debate-card-delete-button {
      position: absolute;
      top: 10px;
      right: 10px;
    }
  `;

  document.head.appendChild(style);
}

function getDebateCardDeleteButtonHtml(debate) {
  if (!canDeleteDebate(debate)) return "";

  if (typeof document !== "undefined") {
    ensureOwnerDeleteButtonStyles();
  }

  return `
    <button
      class="delete-button debate-card-delete-button"
      type="button"
      onclick="event.stopPropagation(); deleteDebate('${debate.id}', false)"
      aria-label="Supprimer cette arène"
      title="Supprimer cette arène"
    >
      <span aria-hidden="true">&times;</span>
    </button>
  `;
}

function getIndexContextClosedPreviewText(text) {
  const fullText = String(text || "").trim();
  if (!fullText) return "";
  const firstSentence = fullText.match(/^.*?[.!?…](?=\s|$)/s);
  if (firstSentence?.[0]) return firstSentence[0].trim();
  const firstLine = fullText.split(/\n+/)[0]?.trim();
  return firstLine || fullText;
}

function buildIndexContextPreviewHtml(debate, scoresHtml = "", metaHtml = "", shareHtml = "", episodeNavHtml = "") {
  const fullText = String(debate?.content || '').trim();
  const hasExtra = !!(scoresHtml || metaHtml || shareHtml || episodeNavHtml);
  if (!fullText && !hasExtra) return "";

  const shortText = getIndexContextClosedPreviewText(fullText);
  const needsToggle = fullText !== shortText || hasExtra;

  const debateId = escapeAttribute(String(debate?.id || ""));

  return `
    <div
      class="debate-card-context"
      data-index-context-card
      role="button"
      tabindex="0"
      onclick="(function(e){ if(e.target.closest('[data-index-context-toggle]')) return; const btn = e.currentTarget.querySelector('[data-index-context-toggle]'); if(btn){ e.preventDefault(); e.stopPropagation(); toggleIndexContextPreview(btn); } })(event)"
      onkeydown="(function(e){ if(e.key==='Enter'||e.key===' '){ const btn = e.currentTarget.querySelector('[data-index-context-toggle]'); if(btn){ e.preventDefault(); toggleIndexContextPreview(btn); } } })(event)"
      style="cursor:pointer;"
    >
      ${fullText ? `<div
        class="debate-card-context-text"
        data-index-context-text
        data-full-text="${escapeAttribute(fullText)}"
        data-short-text="${escapeAttribute(shortText)}"
        data-debate-open="${isOpenDebate(debate) ? '1' : '0'}"
        data-expanded="false"
      ><div class="context-text-clamp">${renderIndexContextPreviewText(shortText, false, isOpenDebate(debate))}</div></div>` : ""}
      ${needsToggle ? `
        <div class="debate-card-context-extra">
          ${scoresHtml}
          ${metaHtml}
          ${shareHtml ? `<div class="debate-card-actions">${shareHtml}</div>` : ""}
          ${episodeNavHtml}
        </div>
      ` : ""}
      ${needsToggle ? `
        <button
          type="button"
          class="debate-card-context-toggle"
          data-index-context-toggle
          data-debate-id="${debateId}"
          aria-expanded="false"
          onclick="event.preventDefault(); event.stopPropagation(); toggleIndexContextPreview(this)"
        ><span>Voir plus</span><span class="debate-card-context-toggle-dots">···</span></button>
      ` : ""}
    </div>
  `;
}

function renderIndexContextPreviewText(text, expanded, isOpen = false) {
  const rawText = String(text || "");
  if (!rawText) return "";
  if (!expanded) {
    return `<b class="context-first-letter">${escapeHtml(rawText[0])}</b>${escapeHtmlNl(rawText.slice(1))}`;
  }
  return renderIndexContextExpandedText(rawText, isOpen);
}

function renderIndexContextExpandedText(text, isOpen = false) {
  const rawText = String(text || "");
  if (!rawText) return "";

  const parts = rawText.split(/\n\n+/)
    .map((part) => part.trim())
    .filter(Boolean);

  if (isOpen) {
    const lastPart = parts[parts.length - 1] || "";
    const latinMotto = parts[parts.length - 2] || "";
    const hasOpenTail = parts.length >= 2;
    if (!hasOpenTail) {
      return `<b class="context-first-letter">${escapeHtml(rawText[0])}</b>${escapeHtmlNl(rawText.slice(1))}`;
    }
    const latinStart = rawText.indexOf(latinMotto);
    const lastStart = latinStart >= 0 ? rawText.indexOf(lastPart, latinStart + latinMotto.length) : -1;
    if (latinStart < 0 || lastStart < 0) {
      return `<b class="context-first-letter">${escapeHtml(rawText[0])}</b>${escapeHtmlNl(rawText.slice(1))}`;
    }
    const beforeLatin = rawText.slice(0, latinStart);
    const betweenLatinAndLast = rawText.slice(latinStart + latinMotto.length, lastStart).replace(/^\n{2,}/, "\n");
    const afterLast = rawText.slice(lastStart + lastPart.length).replace(/^\n{2,}/, "\n");
    const lastHtml = /[?？]$/.test(lastPart)
      ? `<span class="context-reflection-question">${escapeHtml(lastPart)}</span>`
      : escapeHtmlNl(lastPart);
    return `${beforeLatin ? `<b class="context-first-letter">${escapeHtml(beforeLatin[0])}</b>${escapeHtmlNl(beforeLatin.slice(1))}` : ""}<span class="context-latin-question">${escapeHtml(latinMotto)}</span>${escapeHtmlNl(betweenLatinAndLast)}${lastHtml}${escapeHtmlNl(afterLast)}`;
  }

  const signature = parts[parts.length - 1] || "";
  const question = parts[parts.length - 2] || "";
  const hasAgonTail = parts.length >= 3 && /[?？]$/.test(question) && /^(?:[A-Z]\.[A-Z]|[A-Z]\.)\s+\S+/.test(signature);
  const latinQuestion = hasAgonTail && parts.length >= 4 && !/[?？]$/.test(parts[parts.length - 3] || "")
    ? parts[parts.length - 3]
    : "";
  if (!latinQuestion) {
    return `<b class="context-first-letter">${escapeHtml(rawText[0])}</b>${escapeHtmlNl(rawText.slice(1))}`;
  }

  const latinStart = rawText.indexOf(latinQuestion);
  if (latinStart < 0) {
    return `<b class="context-first-letter">${escapeHtml(rawText[0])}</b>${escapeHtmlNl(rawText.slice(1))}`;
  }
  const questionStart = rawText.indexOf(question, latinStart + latinQuestion.length);
  if (questionStart < 0) {
    const beforeLatin = rawText.slice(0, latinStart);
    const afterLatin = rawText.slice(latinStart + latinQuestion.length);
    return `${beforeLatin ? `<b class="context-first-letter">${escapeHtml(beforeLatin[0])}</b>${escapeHtmlNl(beforeLatin.slice(1))}` : ""}<span class="context-latin-question">${escapeHtml(latinQuestion)}</span>${escapeHtmlNl(afterLatin)}`;
  }
  const beforeLatin = rawText.slice(0, latinStart);
  const afterLatin = rawText.slice(latinStart + latinQuestion.length, questionStart).replace(/^\n{2,}/, "\n");
  const signatureStart = hasAgonTail
    ? rawText.indexOf(signature, questionStart + question.length)
    : -1;
  const rawAfterQuestion = rawText.slice(questionStart + question.length, signatureStart >= 0 ? signatureStart : undefined);
  const afterQuestion = signatureStart >= 0 && !rawAfterQuestion.trim()
    ? ""
    : rawAfterQuestion.replace(/^\n{2,}/, "\n");
  const afterSignature = signatureStart >= 0
    ? rawText.slice(signatureStart + signature.length).replace(/^\n{2,}/, "\n")
    : "";
  return `${beforeLatin ? `<b class="context-first-letter">${escapeHtml(beforeLatin[0])}</b>${escapeHtmlNl(beforeLatin.slice(1))}` : ""}<span class="context-latin-question">${escapeHtml(latinQuestion)}</span>${escapeHtmlNl(afterLatin)}<span class="context-debate-question">${escapeHtml(question)}</span>${escapeHtmlNl(afterQuestion)}${signatureStart >= 0 ? `<span class="context-signature">${escapeHtml(signature)}</span>${escapeHtmlNl(afterSignature)}` : ""}`;
}

function closeIndexContextPreview(button) {
  if (!button || button.getAttribute('aria-expanded') !== 'true') return;
  const card = button.closest('[data-index-context-card]');
  const article = button.closest('.debate-card');
  const textEl = card?.querySelector('[data-index-context-text]');
  const metaEl = card?.querySelector('.debate-card-context-extra');
  const shortText = textEl?.getAttribute('data-short-text') || '';
  if (textEl) {
    const clamp = textEl.querySelector('.context-text-clamp');
    if (clamp) clamp.innerHTML = renderIndexContextPreviewText(shortText, false);
    textEl.setAttribute('data-expanded', 'false');
  }
  if (metaEl) metaEl.classList.remove('is-open');
  if (article) article.classList.remove('index-card-context-open');
  button.innerHTML = '<span>Voir plus</span><span class="debate-card-context-toggle-dots">···</span>';
  button.setAttribute('aria-expanded', 'false');
  updateIndexRowContextOpenState(article?.closest?.('.theme-horizontal-row'));
}

function getOpenIndexContextDebateIds() {
  const ids = new Set();
  document.querySelectorAll('[data-index-context-toggle][aria-expanded="true"]').forEach((btn) => {
    const id = btn.getAttribute('data-debate-id');
    if (id) ids.add(id);
  });
  return ids;
}

function restoreOpenIndexContextCards(container, openIds) {
  if (!container || !openIds || !openIds.size) return;
  openIds.forEach((id) => {
    const btn = container.querySelector(`[data-index-context-toggle][data-debate-id="${CSS.escape(id)}"]`);
    if (btn && btn.getAttribute('aria-expanded') !== 'true') {
      toggleIndexContextPreview(btn);
    }
  });
}

function closeOpenContextPreviewsInRow(row, exceptCard = null) {
  if (!row) return false;
  let closedAny = false;
  row.querySelectorAll('[data-index-context-toggle][aria-expanded="true"]').forEach((btn) => {
    const card = btn.closest('.debate-card');
    if (card && card !== exceptCard) {
      closeIndexContextPreview(btn);
      closedAny = true;
    }
  });
  return closedAny;
}

function scrollToIndexRowAfterContextClose(row) {
  if (!row) return;
  const section = row.closest('.theme-row-section') || row;
  setTimeout(() => {
    const top = section.getBoundingClientRect().top + window.scrollY - 8;
    window.scrollTo({ top: Math.max(0, top), behavior: 'smooth' });
  }, 180);
}

function updateIndexRowContextOpenState(row) {
  if (!row) return;
  row.classList.toggle('index-row-context-open', !!row.querySelector('[data-index-context-toggle][aria-expanded="true"]'));
}

function getIndexRowBottomBuffer(row) {
  if (!row) return 2;
  return window.matchMedia("(max-width: 768px)").matches ? 0 : 2;
}

function getIndexCardVisualBottomOffset(card, rowRect) {
  if (!card || !rowRect) return 0;
  const rects = [card.getBoundingClientRect()];
  if (window.matchMedia("(max-width: 768px)").matches) {
    card.querySelectorAll(
      '.debate-card-meta-below-media, .debate-card-counts-row, .debate-card-footer-actions, .debate-card-context-extra, .debate-card-context-toggle'
    ).forEach((el) => {
      const hiddenContextExtra = el.closest('.debate-card-context-extra:not(.is-open)');
      if (hiddenContextExtra) return;
      const style = getComputedStyle(el);
      if (style.display === 'none' || style.visibility === 'hidden') return;
      const rect = el.getBoundingClientRect();
      if (rect && rect.height > 0) rects.push(rect);
    });
  }
  return Math.max(...rects.map((rect) => rect.bottom - rowRect.top));
}

function reserveIndexRowHeightForContextOpen(article, metaEl) {
  const row = article?.closest?.('.theme-horizontal-row');
  if (!row) return;

  updateIndexRowContextOpenState(row);
  if (!article.classList.contains('index-card-context-open')) return;

  const rowRect = row.getBoundingClientRect();
  const articleRect = article.getBoundingClientRect();
  const rowStyle = getComputedStyle(row);
  const bottomPadding = parseFloat(rowStyle.paddingBottom) || 0;
  const articleTop = Math.max(0, articleRect.top - rowRect.top);
  let targetArticleHeight = articleRect.height || article.offsetHeight || 0;

  if (metaEl) {
    const metaStyle = getComputedStyle(metaEl);
    const maxHeightValue = parseFloat(metaStyle.maxHeight);
    const maxVisibleHeight = Number.isFinite(maxHeightValue) && maxHeightValue > 0 ? maxHeightValue : Infinity;
    const targetMetaHeight = Math.min(metaEl.scrollHeight || 0, maxVisibleHeight);
    const currentMetaHeight = metaEl.getBoundingClientRect().height || 0;
    if (targetMetaHeight > currentMetaHeight) {
      targetArticleHeight += targetMetaHeight - currentMetaHeight;
    }
  }

  const visualBottom = getIndexCardVisualBottomOffset(article, rowRect);
  const neededHeight = Math.ceil(
    Math.max(articleTop + targetArticleHeight, visualBottom) + bottomPadding + getIndexRowBottomBuffer(row)
  );
  const currentHeight = parseFloat(row.style.height || '0') || rowRect.height || 0;
  if (neededHeight > currentHeight) {
    row.style.height = `${neededHeight}px`;
  }
}

function syncIndexContextPreviewLayout(button, shouldReveal) {
  const article = button?.closest('.debate-card');
  if (!article) return;

  const row = article.closest('.theme-horizontal-row');
  if (row) {
    updateCarouselCardHighlight(row);
    if (shouldReveal) {
      reserveIndexRowHeightForContextOpen(article, article.querySelector('.debate-card-context-extra'));
    } else {
      updateIndexRowContextOpenState(row);
      // Libère immédiatement la hauteur fixe : le row suit la transition CSS de la carte (max-height 0.34s)
      row.style.height = '';
      // Recalcule hauteur ET position des flèches après la fin des transitions CSS :
      // updateCarouselCardHighlight (plus haut) a pu mesurer le rail encore déplié
      // et corrompre --theme-carousel-button-top (flèches hors du rail).
      setTimeout(() => {
        syncIndexThemeRowHeight(row);
        ensureCarouselHints(row);
        updateIndexThemeRowSwipeButtons(row);
      }, 370);
    }
  }

  if (!shouldReveal) {
    const section = article.closest('.theme-row-section');
    const target = section?.querySelector('.theme-row-title') || article;
    const topbarH = document.querySelector('.topbar')?.offsetHeight || 0;
    const targetTop = target.getBoundingClientRect().top + window.scrollY - topbarH + 8;
    const runScroll = () => {
      window.scrollTo({ top: Math.max(0, targetTop), behavior: 'smooth' });
    };
    if (window.matchMedia("(max-width: 768px)").matches) {
      runScroll();
    } else {
      setTimeout(runScroll, 80);
    }
  }
}

function keepIndexCardSourceImagesAlive(article, durationMs = 5000) {
  if (!article) return;
  const until = String(Date.now() + durationMs);
  article.querySelectorAll('[data-index-og-image-shell]').forEach((shell) => {
    shell.dataset.keepAliveUntil = until;
    if (shell.dataset.rendered !== 'true' && typeof renderIndexOpenGraphImageShell === 'function') {
      renderIndexOpenGraphImageShell(shell);
    }
  });
}

function toggleIndexContextPreview(button) {
  const card = button?.closest('[data-index-context-card]');
  const article = button?.closest('.debate-card');
  const textEl = card?.querySelector('[data-index-context-text]');
  const metaEl = card?.querySelector('.debate-card-context-extra');
  if (!button || (!textEl && !metaEl)) return;

  const nextExpanded = button.getAttribute('aria-expanded') !== 'true';

  // Verrou anti-fermeture accidentelle : bloque la fermeture pendant 400ms après l'ouverture
  if (!nextExpanded && article) {
    const openedAt = Number(article.dataset.contextOpenedAt || 0);
    if (openedAt && Date.now() - openedAt < 400) return;
  }

  if (window.matchMedia("(max-width: 768px)").matches) {
    keepIndexCardSourceImagesAlive(article, nextExpanded ? 5000 : 6500);
  }

  if (textEl) {
    const nextText = nextExpanded
      ? String(textEl.getAttribute('data-full-text') || '')
      : String(textEl.getAttribute('data-short-text') || '');
    const clampSpan = textEl.querySelector('.context-text-clamp');
    if (clampSpan) {
      clampSpan.innerHTML = renderIndexContextPreviewText(nextText, nextExpanded, textEl.getAttribute('data-debate-open') === '1');
    } else {
      textEl.textContent = nextText;
    }
    textEl.setAttribute('data-expanded', nextExpanded ? 'true' : 'false');
  }

  if (metaEl) {
    metaEl.classList.toggle('is-open', nextExpanded);
  }

  if (article) {
    article.classList.toggle('index-card-context-open', nextExpanded);
    if (nextExpanded) {
      article.dataset.contextOpenedAt = String(Date.now());
      const row = article.closest('.theme-horizontal-row');
      if (row) row.dispatchEvent(new Event('index-context-opened'));
    }
  }

  button.innerHTML = nextExpanded
    ? 'Voir moins'
    : '<span>Voir plus</span><span class="debate-card-context-toggle-dots">···</span>';
  button.setAttribute('aria-expanded', nextExpanded ? 'true' : 'false');
  if (nextExpanded) {
    reserveIndexRowHeightForContextOpen(article, metaEl);
  } else {
    updateIndexRowContextOpenState(article?.closest?.('.theme-horizontal-row'));
  }

  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      syncIndexContextPreviewLayout(button, nextExpanded);
    });
  });
}

function handleIndexContextTextKeydown(event, debateId) {
  if (!event) return;

  const key = event.key;
  if (key !== 'Enter' && key !== ' ') return;

  event.preventDefault();
  openIndexDebateFromMedia(debateId, event);
}


