function normalizeArgumentSourceUrl(rawUrl) {
  let value = String(rawUrl || "").trim();
  if (!value) return "";

  if (!/^https?:\/\//i.test(value)) {
    value = "https://" + value;
  }

  try {
    const parsed = new URL(value);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return "";
    return parsed.href;
  } catch (error) {
    return "";
  }
}

function extractArgumentSourceFromBody(bodyValue) {
  const source = { cleanBody: String(bodyValue || ""), url: "" };
  const patterns = [
    /(\n\s*)?↗\s*Source\s*:\s*(https?:\/\/\S+)/i,
    /(\n\s*)?🔗\s*Lien\s*:\s*(https?:\/\/\S+)/i
  ];

  patterns.some((pattern) => {
    const match = source.cleanBody.match(pattern);
    if (!match) return false;

    const rawUrl = String(match[2] || "").replace(/[),.;]+$/g, "");
    const normalizedUrl = normalizeArgumentSourceUrl(rawUrl);
    if (!normalizedUrl) return false;

    source.url = normalizedUrl;
    source.cleanBody = source.cleanBody.replace(match[0], "").trim();
    return true;
  });

  return source;
}

function clearArgumentUrlDraft(normalizedSide) {
  const urlInput = document.getElementById(`${normalizedSide}-url`);
  if (urlInput) {
    urlInput.value = "";
    const field = urlInput.closest(".argument-url-field");
    const preview = field ? field.querySelector("[data-idea-url-preview]") : null;
    if (preview) {
      preview.innerHTML = "";
      preview.removeAttribute("data-state");
    }
  }
}


async function submitArgument(debateId, side) {
  const normalizedSide = side === "B" || side === "b" ? "b" : "a";
  const apiSide = normalizedSide === "b" ? "B" : "A";
  const titleField = document.getElementById(`${normalizedSide}-title`);
  const bodyField = document.getElementById(`${normalizedSide}-body`);
  const warning = document.getElementById(`warning-${normalizedSide}`);
  const form = document.getElementById(`form-${normalizedSide}`);
  const submitButton = form?.querySelector('button[type="submit"]') || null;

  if (!titleField || !bodyField) return;

  const title = titleField.value.trim();
  const rawBody = bodyField.value.trim();
  const sourceUrlInput = document.getElementById(`${normalizedSide}-url`);
  const extractedSource = extractArgumentSourceFromBody(rawBody);
  const sourceUrl = normalizeArgumentSourceUrl(sourceUrlInput?.value || "") || extractedSource.url;
  let body = String(extractedSource.cleanBody || "").trim();
  const pasteMeta = computeArgumentPasteMeta(normalizedSide, title, rawBody);

  if (sourceUrlInput && String(sourceUrlInput.value || "").trim() && !sourceUrl) {
    alert("Le lien URL semble invalide. Utilise un format du type https://exemple.com");
    sourceUrlInput.focus();
    return;
  }

  const maxBodyLength = bodyField.maxLength > 0 ? bodyField.maxLength : 600;
  if (rawBody.length > maxBodyLength) {
    alert(`Maximum ${maxBodyLength} caractères pour le texte de l'idée.`);
    return;
  }

  if (!title) {
    showReplacementSuccessMessage(
      "Idée manquante",
      "Tu dois écrire un titre à cette idée avant de la publier.",
      null,
      "⚠️"
    );
    return;
  }

  const confirmed = await showIdeaPublishConfirmModal();
  if (!confirmed) {
    return;
  }

  setButtonLoading(submitButton);

  try {
    stopIdeaVoiceDictation();
    const r = await fetchJSON(API + "/arguments", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        debate_id: debateId,
        side: apiSide,
        title,
        body,
        source_url: sourceUrl || "",
        authorKey: getKey(),
        pasteRatio: pasteMeta.pasteRatio,
        pastedChars: pasteMeta.pastedChars,
        manualWritingBadge: pasteMeta.manualWritingBadge,
        usedMicrophone: pasteMeta.usedMicrophone,
        paste_ratio: pasteMeta.pasteRatio,
        pasted_chars: pasteMeta.pastedChars,
        manual_writing_badge: pasteMeta.manualWritingBadge,
        used_microphone: pasteMeta.usedMicrophone
      })
    });

    if (!isAdmin()) {
      saveLocalArgumentPasteMeta(r.id, pasteMeta);
    }

    titleField.value = "";
    bodyField.value = "";
    clearArgumentUrlDraft(normalizedSide);
    resetArgumentPasteDraftStats(normalizedSide);
    resetArgumentVoiceDraftStats(normalizedSide);

    if (warning) {
      warning.style.display = "none";
    }

    if (form) {
      form.style.display = "none";
    }

    openedArgumentForm = null;
    document.body.classList.remove("argument-form-open");
    syncIframeParentArgumentFormState(false);

    if (typeof updateCounter === "function") {
      updateCounter(`${normalizedSide}-title`, `count-title-${normalizedSide}`, 100);
      updateCounter(`${normalizedSide}-body`, `count-body-${normalizedSide}`, 600);
    }

    pendingArgumentScrollId = String(r.id);
    pinnedNewArgumentId = String(r.id);

    try {
      insertLocalArgumentAfterPublish(debateId, {
        id: r.id,
        debate_id: debateId,
        side: apiSide,
        title,
        body,
        source_url: sourceUrl || "",
        pasteRatio: pasteMeta.pasteRatio,
        pastedChars: pasteMeta.pastedChars,
        manualWritingBadge: pasteMeta.manualWritingBadge,
        usedMicrophone: pasteMeta.usedMicrophone,
        paste_ratio: pasteMeta.pasteRatio,
        pasted_chars: pasteMeta.pastedChars,
        manual_writing_badge: pasteMeta.manualWritingBadge,
        used_microphone: pasteMeta.usedMicrophone
      });

      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          scrollToTopOfArgumentCardAndFlash(String(r.id));
        });
      });
    } catch (localRenderError) {
      console.error(localRenderError);
      await loadDebate(debateId);
    }

    showPushInviteAfterAction("argument");
  } catch (error) {
    alert(error.message);
  } finally {
    clearButtonLoading(submitButton);
  }
}

